const COLLECTION_DATA = {
  cms:         { title: 'Count-Min Sketch',              file: 'collection/cms.html',         tag: 'Algorithm' },
  topk:        { title: 'Top-K End-to-End Design',       file: 'collection/topk.html',        tag: 'System Design' },
  ai_handbook: { title: 'AI Leadership Handbook',        file: 'collection/ai_handbook.html', tag: 'AI / Leadership' },
  databases:   { title: 'Databases Compared',            srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Database Showdown: PostgreSQL vs MongoDB vs DynamoDB vs Cassandra</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;--pg:#336791;--pg-bg:#eef4fb;--mg:#13aa52;--mg-bg:#edfaf2;--dy:#ff9900;--dy-bg:#fff8ec;--ca:#1287b1;--ca-bg:#eaf6fb;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-pg{border-color:#336791;color:#336791;background:rgba(51,103,145,.08);}\n.pill-mg{border-color:#13aa52;color:#13aa52;background:rgba(19,170,82,.08);}\n.pill-dy{border-color:#ff9900;color:#cc7a00;background:rgba(255,153,0,.08);}\n.pill-ca{border-color:#1287b1;color:#1287b1;background:rgba(18,135,177,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.pg::before{background:var(--pg);}\n.db-card.mg::before{background:var(--mg);}\n.db-card.dy::before{background:var(--dy);}\n.db-card.ca::before{background:var(--ca);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}\n.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8c4b8;border:1px solid #1e1c18;}\n.codeblock .c{color:#3e3d36;}.codeblock .k{color:#e8b84b;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .t{color:#7aaee0;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.dot{display:inline-block;width:9px;height:9px;border-radius:50%;margin-right:4px;vertical-align:middle;}\n.dot.g{background:var(--green);}.dot.a{background:var(--amber);}.dot.r{background:var(--red);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.shard-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:20px 0;}\n.shard-card{background:var(--ink);border-radius:8px;padding:20px;color:#c8c4b8;}\n.shard-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.shard-name{font-family:var(--serif);font-size:16px;font-weight:700;color:#e8b84b;margin-bottom:8px;}\n.shard-body{font-size:12.5px;line-height:1.65;color:#a8a49c;}\n.shard-verdict{margin-top:10px;font-family:var(--mono);font-size:10px;padding:4px 10px;border-radius:3px;display:inline-block;}\n.sv-easy{background:rgba(26,122,74,.2);color:#5ac882;}.sv-med{background:rgba(184,114,10,.2);color:#e8943a;}.sv-hard{background:rgba(192,57,43,.2);color:#e87868;}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-pg{background:var(--pg-bg);border-color:var(--pg);color:var(--pg);}.b-mg{background:var(--mg-bg);border-color:var(--mg);color:var(--mg);}.b-dy{background:var(--dy-bg);border-color:var(--dy);color:#b06000;}.b-ca{background:var(--ca-bg);border-color:var(--ca);color:var(--ca);}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 Database Selection \u00b7 Manish-Almanac</div>\n    <h1>The Database<br><em>Showdown</em></h1>\n    <p class=\"hero-sub\">PostgreSQL vs MongoDB vs DynamoDB vs Cassandra \u2014 every dimension that matters in a FAANG interview, explained so clearly a layman would get it. Includes real system design examples and every follow-up question.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-pg\">PostgreSQL</span>\n      <span class=\"db-pill pill-mg\">MongoDB</span>\n      <span class=\"db-pill pill-dy\">DynamoDB</span>\n      <span class=\"db-pill pill-ca\">Cassandra</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#intuition\">Intuition</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#sharding\">Sharding</a>\n  <a href=\"#consistency\">Consistency</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"intuition\">\n  <div class=\"sec-tag\">00 \u00b7 Start Here</div>\n  <h2>Before picking a database, answer one question</h2>\n  <p>Most candidates jump straight to \"I'll use PostgreSQL\" or \"I'll use Cassandra\" without justifying the choice. The interviewer doesn't care which database you pick \u2014 they care <strong>whether you understand what each is optimised for and why it matches your access pattern</strong>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The filing cabinet analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      Imagine you're running a law firm with four types of filing systems:<br><br>\n      <strong>PostgreSQL</strong> is a meticulous paralegal with a master index. Ask anything \u2014 \"all cases involving John AND contract law from 2022\" \u2014 and they find it. But they can only work so fast, and adding more paralegals requires careful coordination.<br><br>\n      <strong>MongoDB</strong> is a flexible folder system. Each folder can hold anything \u2014 a mix of documents, photos, notes. Great when your documents have varying shapes and you're still figuring out what you need to ask.<br><br>\n      <strong>DynamoDB</strong> is a warehouse with perfectly labelled shelves. If you know the shelf number, retrieval is instant and the warehouse grows infinitely. But you can only ask \"what's on shelf 7B\" \u2014 not \"show me everything red.\"<br><br>\n      <strong>Cassandra</strong> is a warehouse distributed across 10 cities. Every city holds a copy of relevant files. Writes go to all 10 simultaneously. No city going down stops you. But reorganising the filing system later is painful.\n    </div>\n  </div>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The only three questions that matter</div>\n    <p><strong>1. What is your write pattern?</strong> Low-volume transactional writes (PostgreSQL/MongoDB) vs high-throughput append-heavy writes (Cassandra/DynamoDB)?</p>\n    <p><strong>2. What is your read pattern?</strong> Flexible ad-hoc queries (PostgreSQL) vs known key-based lookups (DynamoDB/Cassandra)?</p>\n    <p><strong>3. Do you need ACID transactions?</strong> If yes: PostgreSQL. If no: the others can offer far more scale.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four Databases \u2014 Their Core Identity</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card pg\">\n      <div class=\"db-logo\">\ud83d\udc18</div>\n      <div class=\"db-name\">PostgreSQL</div>\n      <div class=\"db-type\">Relational \u00b7 RDBMS</div>\n      <div class=\"db-tagline\">The Swiss Army knife. When in doubt, reach for Postgres. ACID transactions, joins, complex queries, full-text search, JSON support, and extensions for almost anything.</div>\n      <div class=\"db-born\">Born 1996 \u00b7 Open Source \u00b7 UC Berkeley lineage</div>\n    </div>\n    <div class=\"db-card mg\">\n      <div class=\"db-logo\">\ud83c\udf43</div>\n      <div class=\"db-name\">MongoDB</div>\n      <div class=\"db-type\">Document \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The developer favourite. Store JSON-like documents with flexible schemas. Great when your data is hierarchical, varies in shape, and you want to iterate fast without migrations.</div>\n      <div class=\"db-born\">Born 2009 \u00b7 MongoDB Inc \u00b7 Document model</div>\n    </div>\n    <div class=\"db-card dy\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">DynamoDB</div>\n      <div class=\"db-type\">Key-Value / Document \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The infinite scaler. Amazon's fully managed beast. Sub-10ms at any scale, automatic partitioning, built-in TTL, zero operational burden. You pay for predictability.</div>\n      <div class=\"db-born\">Born 2012 \u00b7 AWS Managed \u00b7 Dynamo paper lineage</div>\n    </div>\n    <div class=\"db-card ca\">\n      <div class=\"db-logo\">\ud83d\udc8e</div>\n      <div class=\"db-name\">Cassandra</div>\n      <div class=\"db-type\">Wide-Column \u00b7 NoSQL</div>\n      <div class=\"db-tagline\">The write monster. Designed for 500K writes/sec across multiple data centers. No single point of failure. Used by Netflix, Apple, Discord. But design your tables around your queries \u2014 upfront.</div>\n      <div class=\"db-born\">Born 2008 \u00b7 Apache \u00b7 Facebook lineage</div>\n    </div>\n  </div>\n\n  <h3>The Mental Model: What Type of Storage Are They Really?</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Database</th><th>Core Data Unit</th><th>Primary Access Pattern</th><th>Think of it as</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">PostgreSQL</td><td>Row in a table</td><td>Any SQL \u2014 joins, aggregations, filters</td><td>Excel spreadsheet with a PhD</td></tr>\n      <tr><td class=\"row-head\">MongoDB</td><td>JSON Document</td><td>Query by any field in the document</td><td>A folder of JSON files with indexes</td></tr>\n      <tr><td class=\"row-head\">DynamoDB</td><td>Item (key-value)</td><td>Get by partition key (+ optional sort key)</td><td>A perfectly organised hashmap in the cloud</td></tr>\n      <tr><td class=\"row-head\">Cassandra</td><td>Row in a partition</td><td>Query by partition key, range on clustering key</td><td>Distributed sorted log, partitioned globally</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">02 \u00b7 The Full Picture</div>\n  <h2>Every Dimension That Matters in an Interview</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>PostgreSQL \ud83d\udc18</th><th>MongoDB \ud83c\udf43</th><th>DynamoDB \u26a1</th><th>Cassandra \ud83d\udc8e</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Data Model</td><td>Relational \u2014 strict schema</td><td>Document \u2014 flexible JSON</td><td>Key-value + document</td><td>Wide-column \u2014 partition + clustering</td></tr>\n      <tr><td class=\"row-head\">Write Throughput</td><td><span class=\"warn\">~5K\u201320K TPS</span> single node</td><td><span class=\"warn\">~20K\u201350K</span> writes/sec</td><td><span class=\"good\">Millions/sec</span> auto-scaled</td><td><span class=\"good\">500K\u20131M</span> writes/sec</td></tr>\n      <tr><td class=\"row-head\">Read Latency</td><td><span class=\"warn\">1ms\u2013seconds</span> query-dependent</td><td><span class=\"warn\">1ms\u2013100ms</span> index-dependent</td><td><span class=\"good\">Sub-10ms</span> guaranteed</td><td><span class=\"good\">Sub-10ms</span> on partition key</td></tr>\n      <tr><td class=\"row-head\">ACID Transactions</td><td><span class=\"good\">Full ACID</span> multi-table</td><td><span class=\"warn\">Partial</span> multi-doc in v4+ (slow)</td><td><span class=\"warn\">Single-item ACID</span> only</td><td><span class=\"bad\">Limited</span> single-partition only</td></tr>\n      <tr><td class=\"row-head\">Query Flexibility</td><td><span class=\"good\">Unlimited</span> \u2014 full SQL</td><td><span class=\"good\">High</span> \u2014 any field</td><td><span class=\"bad\">Very limited</span> \u2014 by key only</td><td><span class=\"warn\">Constrained</span> \u2014 design for queries</td></tr>\n      <tr><td class=\"row-head\">Horizontal Scale</td><td><span class=\"bad\">Hard</span> \u2014 Citus or manual</td><td><span class=\"warn\">Built-in</span> but complex</td><td><span class=\"good\">Invisible</span> \u2014 AWS auto</td><td><span class=\"good\">Native</span> \u2014 add nodes</td></tr>\n      <tr><td class=\"row-head\">Multi-Region HA</td><td><span class=\"bad\">Manual setup</span></td><td><span class=\"warn\">Replica sets</span></td><td><span class=\"good\">Global Tables</span> managed</td><td><span class=\"good\">Native</span> multi-DC</td></tr>\n      <tr><td class=\"row-head\">Schema Flexibility</td><td><span class=\"bad\">Rigid</span> \u2014 migrations needed</td><td><span class=\"good\">Fully flexible</span></td><td><span class=\"good\">Flexible</span> \u2014 keys only fixed</td><td><span class=\"warn\">Semi-rigid</span> \u2014 upfront design</td></tr>\n      <tr><td class=\"row-head\">Consistency</td><td><span class=\"good\">Strong</span> \u2014 serialisable</td><td><span class=\"warn\">Tunable</span> via write concern</td><td><span class=\"warn\">Eventual default</span>, strong 2x cost</td><td><span class=\"warn\">Tunable</span> ONE/QUORUM/ALL</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"warn\">Self-managed</span></td><td><span class=\"warn\">Self or Atlas</span></td><td><span class=\"good\">Zero ops</span></td><td><span class=\"bad\">High</span> \u2014 complex</td></tr>\n      <tr><td class=\"row-head\">Scale Ceiling</td><td>~10TB, ~50K TPS</td><td>~100TB sharded</td><td>Unlimited (managed)</td><td>Petabyte scale</td></tr>\n      <tr><td class=\"row-head\">Who Uses It</td><td>Instagram, GitHub, Shopify</td><td>Forbes, eBay, EA Games</td><td>Amazon, Lyft, Airbnb</td><td>Netflix, Apple, Discord</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"sharding\">\n  <div class=\"sec-tag\">03 \u00b7 The Hard Part</div>\n  <h2>Sharding \u2014 How Each Database Splits Data Across Machines</h2>\n  <p>Sharding is splitting your data across multiple machines so no single machine holds everything. This is the most-tested topic in FAANG interviews because it forces you to confront real trade-offs.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Sharding explained with a phone book</div>\n    <div class=\"analogy-text\">\n      You have a phone book with 1 billion entries. It's too heavy for one shelf. You split it:<br><br>\n      <strong>Range sharding</strong> \u2014 A\u2013F on shelf 1, G\u2013M on shelf 2, N\u2013Z on shelf 3. Simple, but \"S\" names might dominate (hot shard).<br><br>\n      <strong>Hash sharding</strong> \u2014 Run the name through a hash function, result tells you which shelf. Perfectly balanced, but you can't look up \"everyone between Adams and Brown\" anymore.<br><br>\n      <strong>Consistent hashing</strong> \u2014 Like hash sharding but when you add a new shelf, you only move a fraction of entries, not half of everything.\n    </div>\n  </div>\n  <div class=\"shard-grid\">\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">PostgreSQL</div>\n      <div class=\"shard-name\">Manual / Citus</div>\n      <div class=\"shard-body\">Postgres doesn't shard natively. You either shard at the application layer or use the Citus extension. Both are complex to operate. Cross-shard joins require careful design. Great for read replicas; write sharding is painful.</div>\n      <span class=\"shard-verdict sv-hard\">HARD \u2014 DIY or Citus</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">MongoDB</div>\n      <div class=\"shard-name\">Built-in Sharding</div>\n      <div class=\"shard-body\">Native range and hash sharding via a mongos router. Shard key choice is the most critical decision. Bad shard key (low cardinality or monotonically increasing) causes hot spots and is very hard to fix after the fact.</div>\n      <span class=\"shard-verdict sv-med\">MEDIUM \u2014 Built-in but tricky</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">DynamoDB</div>\n      <div class=\"shard-name\">Invisible Partitioning</div>\n      <div class=\"shard-body\">AWS handles all partitioning automatically based on your partition key using consistent hashing. You just define a good partition key (high cardinality, evenly distributed). Hot partitions are still your problem if keys are skewed.</div>\n      <span class=\"shard-verdict sv-easy\">EASY \u2014 AWS managed</span>\n    </div>\n    <div class=\"shard-card\">\n      <div class=\"shard-title\">Cassandra</div>\n      <div class=\"shard-name\">Token Ring</div>\n      <div class=\"shard-body\">Uses a consistent hash token ring. Each node owns a range of tokens. Data is hashed to a token, written to that node + N replicas. Adding nodes redistributes tokens automatically. No downtime for scaling.</div>\n      <span class=\"shard-verdict sv-easy\">EASY \u2014 Native, automatic</span>\n    </div>\n  </div>\n\n  <h3>The Hot Partition Problem \u2014 All Four Face It</h3>\n  <div class=\"callout cl-red\">\n    <div class=\"cl-lbl\">\u26a0\ufe0f The problem interviewers always probe</div>\n    <p><strong>What it is:</strong> One shard/partition gets disproportionately more traffic. Example: a celebrity user \u2014 all writes for their posts hit the same shard.</p>\n    <p><strong>The fix (universal):</strong> Add a random suffix \u2014 write <code>user_123#0</code> through <code>user_123#7</code>. This distributes across 8 shards. A scatter-gather read merges results. Or use write-time fan-out.</p>\n    <p><strong>Cassandra-specific:</strong> Time-based keys cause one partition per time window to become hot during peak. Use bucketing: <code>entity_type + date_bucket</code> as partition key to distribute load.</p>\n    <p><strong>DynamoDB-specific:</strong> Adaptive Capacity auto-absorbs bursts, but consistent hot keys still cause throttling. Write sharding with a <code>#bucket</code> suffix is the right fix.</p>\n  </div>\n\n  <h3>Partition Key Design Rules</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Rule</th><th>Good Example</th><th>Bad Example</th><th>Why Bad</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">High cardinality</td><td><code>user_id</code> (millions of users)</td><td><code>country</code> (only ~200 values)</td><td>All US users hit one shard</td></tr>\n      <tr><td class=\"row-head\">Even distribution</td><td><code>hash(user_id)</code></td><td><code>timestamp</code></td><td>All current writes hit the newest partition</td></tr>\n      <tr><td class=\"row-head\">Matches access pattern</td><td><code>entity_type + region</code> for Top-K</td><td><code>event_id</code> (never queried directly)</td><td>Every query needs a full scan</td></tr>\n      <tr><td class=\"row-head\">Not monotonically increasing</td><td><code>uuid_v4()</code></td><td><code>auto_increment id</code></td><td>All inserts go to the last partition</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"consistency\">\n  <div class=\"sec-tag\">04 \u00b7 CAP Theorem in Practice</div>\n  <h2>Consistency, Availability, Partition Tolerance</h2>\n  <p>CAP theorem: in a distributed system, you can guarantee only two of: <strong>Consistency</strong> (every read gets the latest write), <strong>Availability</strong> (every request gets a response), <strong>Partition Tolerance</strong> (system works even if network splits). Since network partitions always happen, the real choice is <strong>CP vs AP</strong>.</p>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">Plain English</div>\n    <p><strong>CP (Consistency + Partition Tolerance):</strong> \"I'd rather return an error than return stale data.\" A bank is CP \u2014 you never want a wrong balance.</p>\n    <p><strong>AP (Availability + Partition Tolerance):</strong> \"I'd rather return slightly old data than nothing.\" Twitter's trending list is AP \u2014 seeing a hashtag ranked #3 vs #4 is fine.</p>\n  </div>\n  <table class=\"comp-table\">\n    <thead><tr><th>Database</th><th>CAP</th><th>Default Consistency</th><th>Tunable?</th><th>Best For</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">PostgreSQL</td><td><strong>CP</strong></td><td>Serialisable / Read Committed</td><td>Yes \u2014 isolation levels</td><td>Financial transactions, inventory</td></tr>\n      <tr><td class=\"row-head\">MongoDB</td><td><strong>CP default</strong></td><td>Strong (writeConcern: majority)</td><td>Yes \u2014 read/write concerns</td><td>User profiles, catalogs, CMS</td></tr>\n      <tr><td class=\"row-head\">DynamoDB</td><td><strong>AP default</strong></td><td>Eventually consistent</td><td>Yes \u2014 strong reads at 2x cost</td><td>Sessions, carts, leaderboards</td></tr>\n      <tr><td class=\"row-head\">Cassandra</td><td><strong>AP tunable</strong></td><td>Eventual (ONE)</td><td>Yes \u2014 QUORUM for strong</td><td>IoT, time-series, event logs</td></tr>\n    </tbody>\n  </table>\n\n  <h3>Cassandra Consistency Levels \u2014 Understand This Deeply</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">ONE</div><div class=\"concept-def\"><strong>Confirmed by 1 replica.</strong> Fastest. Least consistent. If that one node is behind, you get stale data.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: metrics, logs \u2014 stale reads are acceptable.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">QUORUM</div><div class=\"concept-def\"><strong>Confirmed by majority: (RF/2)+1 = 2 of 3 replicas.</strong> Balanced speed and correctness.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: user data, session state. Write QUORUM + Read QUORUM = 4 &gt; RF(3) \u2192 guaranteed to read your own writes.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">ALL</div><div class=\"concept-def\"><strong>Confirmed by ALL replicas.</strong> Strongest consistency. One node down = total failure.<br><span style=\"color:#5a5848;font-size:12.5px;\">Best for: financial data only. Rarely used in practice.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">The Golden Rule</div><div class=\"concept-def\"><code>write_CL + read_CL &gt; RF</code> \u2192 guaranteed to read your own writes.<br><br><span style=\"color:#1a7a4a;font-size:13px;\">\u2713 QUORUM(2) + QUORUM(2) = 4 &gt; RF(3) \u2192 Strong consistency</span><br><span style=\"color:#b83030;font-size:13px;\">\u2717 ONE(1) + ONE(1) = 2 &lt; RF(3) \u2192 May read stale data</span></div></div>\n</div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>Which Database Wins in Which System?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">500K EVENTS/SEC</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">HOT STORE</div><div class=\"choice-val\"><span class=\"badge b-g\">Redis ZSET</span> Not one of the four \u2014 Redis wins for real-time sorted sets. ZINCRBY + ZREVRANGE at sub-ms. None of the four match this for live ranking.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WARM STORE</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> 50K rows/sec from Flink flush. Partition by entity_type+region, cluster by window_bucket. Range queries by time are Cassandra's home ground. PostgreSQL would be bottlenecked at this write rate.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">Why NOT Postgres</div><div class=\"choice-val\"><span class=\"badge b-r\">PostgreSQL \u2717</span> Sustained 50K writes/sec saturates a single node. Sharding Postgres is operationally complex. And we don't need joins \u2014 pre-aggregated counts need no relational features.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">Why NOT DynamoDB</div><div class=\"choice-val\"><span class=\"badge b-a\">DynamoDB \u26a0</span> Could work technically but cost is prohibitive. At $1.25 per million writes \u00d7 4.3B writes/day \u2248 $5,400/day. Cassandra on 10 nodes \u2248 $200/day at the same scale.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ride-Sharing App (Uber)</div>\n      <span class=\"sd-example-tag\">MIXED WORKLOAD</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">RIDE ENTITY</div><div class=\"choice-val\"><span class=\"badge b-pg\">PostgreSQL \u2713</span> Ride lifecycle: create \u2192 assign driver \u2192 update status \u2192 charge payment \u2192 close. You need ACID transactions across tables. PostgreSQL prevents double-assignment and double-charging atomically.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">DRIVER LOCATION</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> Location history: partition by driver_id, cluster by timestamp DESC. For real-time queries use Redis GEOADD. Cassandra stores the durable time-series history.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">USER PROFILES</div><div class=\"choice-val\"><span class=\"badge b-mg\">MongoDB \u2713</span> Profiles vary: saved addresses, payment methods, preferences, ratings. Document model is natural. No joins needed \u2014 just fetch the user document by user_id.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SESSION TOKENS</div><div class=\"choice-val\"><span class=\"badge b-dy\">DynamoDB \u2713</span> Token \u2192 user_id + expiry. DynamoDB TTL auto-expires sessions. Millions of sessions, single-key lookups, zero ops. Perfect fit.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">E-Commerce (Amazon-style)</div>\n      <span class=\"sd-example-tag\">MULTI-MODEL</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDERS / PAYMENTS</div><div class=\"choice-val\"><span class=\"badge b-pg\">PostgreSQL \u2713</span> Money moves. \"Deduct inventory AND create order AND charge payment\" must be atomic. PostgreSQL's ACID guarantees this in a single transaction. Nothing else on this list does it reliably.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">PRODUCT CATALOG</div><div class=\"choice-val\"><span class=\"badge b-mg\">MongoDB \u2713</span> A T-shirt has size/color. A laptop has RAM/CPU. A book has ISBN. Product attributes vary wildly \u2014 flexible schema is perfect. Add new product types without migration.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">SHOPPING CART</div><div class=\"choice-val\"><span class=\"badge b-dy\">DynamoDB \u2713</span> Cart = user_id \u2192 [items]. Single-key access. TTL to expire abandoned carts. Millions of concurrent sessions. Zero ops burden.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">ORDER HISTORY</div><div class=\"choice-val\"><span class=\"badge b-ca\">Cassandra \u2713</span> \"All orders for user X sorted by date\" \u2014 perfect Cassandra query. Partition by user_id, cluster by order_date DESC. Append-only, high write throughput during sale events.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to Pick in an Interview \u2014 in 60 Seconds</h2>\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick a Database \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need ACID transactions across multiple entities?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">\u2713 YES \u2192</span><span class=\"opt-text\"><strong>PostgreSQL. Full stop.</strong> Financial data, inventory, orders \u2014 anything where a failed write must roll back atomically across tables.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">\u2192 NO \u2192</span><span class=\"opt-text\">Continue to Step 2.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your write volume?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">&lt;10K/sec \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or MongoDB.</strong> Single-node handles this comfortably with proper indexing.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">10K\u2013100K/sec \u2192</span><span class=\"opt-text\"><strong>MongoDB (sharded) or DynamoDB.</strong> Need horizontal write scaling.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">&gt;100K/sec \u2192</span><span class=\"opt-text\"><strong>Cassandra or DynamoDB.</strong> Built for massive write throughput \u2014 Cassandra handles 500K+/sec.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your read pattern?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Ad-hoc SQL \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or MongoDB.</strong> Joins, filters, aggregations, full-text search \u2014 all supported.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Key lookups \u2192</span><span class=\"opt-text\"><strong>DynamoDB or Cassandra.</strong> Always querying by user_id, entity_id \u2014 single-key access patterns.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Range by time \u2192</span><span class=\"opt-text\"><strong>Cassandra.</strong> Partition by entity, cluster by timestamp DESC \u2014 its strongest access pattern.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you control your infrastructure?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Self-hosted \u2192</span><span class=\"opt-text\"><strong>PostgreSQL / Cassandra / MongoDB.</strong> Cost-efficient at scale, full control.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Managed \u2192</span><span class=\"opt-text\"><strong>DynamoDB.</strong> Zero ops, auto-scaling, AWS-native. Pay for predictability.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n      <div class=\"step-q\">Does your schema change frequently?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Still evolving \u2192</span><span class=\"opt-text\"><strong>MongoDB.</strong> Flexible document model \u2014 add fields to individual documents without migration.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Stable \u2192</span><span class=\"opt-text\"><strong>PostgreSQL or Cassandra.</strong> Schema stability enables better optimisation.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <h3>The Rules You Must Know</h3>\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--pg)\">\ud83d\udc18 Never use PostgreSQL for\u2026</div>\n      <ul><li>Write-heavy workloads &gt;50K TPS</li><li>Multi-region active-active writes</li><li>Flexible evolving schemas</li><li>IoT sensor streams (millions of tiny writes)</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--mg)\">\ud83c\udf43 Never use MongoDB for\u2026</div>\n      <ul><li>Strict ACID transactions at high volume</li><li>Write throughput &gt;100K/sec reliably</li><li>Inherently relational data with complex joins</li><li>When you need Cassandra-style time partitioning</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc8800\">\u26a1 Never use DynamoDB for\u2026</div>\n      <ul><li>Ad-hoc queries (pay for full table scans)</li><li>Complex joins or aggregations</li><li>High-volume cross-item ACID transactions</li><li>Non-AWS deployments</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--ca)\">\ud83d\udc8e Never use Cassandra for\u2026</div>\n      <ul><li>ACID transactions or financial data</li><li>Ad-hoc queries</li><li>Small teams without ops expertise</li><li>Frequently changing query patterns</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why not just use PostgreSQL for everything?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>This is right for 80% of startups.</strong> With proper indexing and read replicas, Postgres handles tens of thousands of TPS and terabytes of data. Instagram ran on PostgreSQL until billions of photos \u2014 they added sharding only when forced.<br><br>The threshold: when you need <strong>multi-region active-active writes</strong>, <strong>&gt;50K sustained writes/sec</strong>, or <strong>petabyte-scale storage</strong>. Below those thresholds, Postgres with read replicas is correct and introduces less complexity.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Cassandra says \"no joins\" \u2014 how does a social app do \"get tweets liked by users I follow\"?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Denormalise and pre-compute.</strong> Design tables for your queries, not your entities.<br><br>Store <code>user_liked_tweets(user_id, tweet_id, liked_at)</code> for \"show me what I liked.\" Store <code>tweet_liked_by(tweet_id, user_id)</code> for \"show me who liked this tweet.\" Same data, two tables, two access patterns. Write fan-out handles both. Storage is cheap; compute is expensive.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">DynamoDB vs Cassandra \u2014 they seem to do the same thing?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">They share a heritage (Dynamo paper) but differ in practice:<br><br><strong>DynamoDB:</strong> Fully managed, AWS-only, pay per request, zero ops. Expensive at massive scale, AWS lock-in.<br><br><strong>Cassandra:</strong> Self-hosted or Astra, any cloud, pay for machines. Requires ops expertise. Dramatically cheaper at extreme scale \u2014 Netflix uses it because at their scale (trillions of rows) savings justify the ops investment.<br><br>Decision: <strong>team size and cloud commitment.</strong> Small team on AWS \u2192 DynamoDB. Large team, predictable massive load \u2192 Cassandra.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How does Cassandra handle a node going down mid-write?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Hinted Handoff + Read Repair.</strong><br><br><strong>Hinted Handoff:</strong> Write to 3 nodes; node 2 is down. Coordinator stores a hint \u2014 \"send this write to node 2 when it recovers.\" Node 2 receives all missed writes on restart.<br><br><strong>Read Repair:</strong> On a QUORUM read, if replicas return different values, Cassandra detects inconsistency and repairs the stale replica in the background.<br><br><strong>Anti-Entropy Repair:</strong> Weekly background process comparing replicas via Merkle trees. Skipping this causes data loss over time.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">When would you choose MongoDB over PostgreSQL?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">MongoDB wins when:<br><br><strong>1. Schema is genuinely unknown or rapidly evolving</strong> \u2014 CMS, product catalog with 50 different product types, configuration system. Each document legitimately has different fields.<br><br><strong>2. Data is hierarchically structured</strong> \u2014 blog post with embedded comments, tags, and author info as one document. Faster than 4 JOINed tables.<br><br><strong>3. Prototyping fast without a DBA</strong> \u2014 no migrations, no ALTER TABLE.<br><br><strong>MongoDB loses when:</strong> You need transactions, your \"flexible\" schema has become inconsistent garbage no one understands, or your aggregation pipeline is 200 lines of nested JSON.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between a secondary index in DynamoDB vs Cassandra?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>DynamoDB:</strong> Two types \u2014 Local Secondary Index (same partition key, different sort key, created at table creation, can't be deleted) and Global Secondary Index (different partition key entirely, created any time, has its own read/write capacity). GSIs are eventually consistent and cost additional write capacity units for every write to the base table.<br><br><strong>Cassandra:</strong> Secondary indexes are a trap. They scatter queries across all nodes (each node checks its local data), creating latency spikes and hot spots. <strong>The correct Cassandra approach is to create a new table</strong> denormalised for the access pattern, not add a secondary index. Materialized Views are an alternative but have their own consistency trade-offs.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">DATABASES \u00b7 POSTGRESQL \u00b7 MONGODB \u00b7 DYNAMODB \u00b7 CASSANDRA \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Databases' },
  olap:        { title: 'OLAP Engines Compared',         srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>OLAP Showdown: ClickHouse vs Druid vs BigQuery vs Redshift</title>\n<link href=\"https://fonts.googleapis.com/css2?family=DM+Serif+Display:ital@0;1&family=DM+Sans:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#08090d;--page:#f0f2f8;--surface:#e4e7f0;--surface2:#d8dcea;--border:#c8ccda;--muted:#6a6e7e;--ch:#f90000;--ch-bg:#fff0f0;--dr:#3ea8ff;--dr-bg:#eef6ff;--bq:#4285f4;--bq-bg:#eef2ff;--rs:#ff9900;--rs-bg:#fff6ee;--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--purple:#6040a0;--purple-bg:#f2eefb;--mono:'JetBrains Mono',monospace;--serif:'DM Serif Display',serif;--sans:'DM Sans',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e0e4f0;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:radial-gradient(ellipse 60% 50% at 80% 50%,rgba(63,168,255,.06) 0%,transparent 70%);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#4a4e5e;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(30px,5vw,56px);font-weight:400;font-style:italic;line-height:1.08;letter-spacing:-.5px;margin-bottom:20px;color:#f0f2fa;}\nh1 em{color:#3ea8ff;font-style:normal;}\n.hero-sub{font-size:15px;color:#6a6e7e;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-ch{border-color:#f90000;color:#c00;background:rgba(249,0,0,.06);}\n.pill-dr{border-color:#3ea8ff;color:#2080cc;background:rgba(62,168,255,.06);}\n.pill-bq{border-color:#4285f4;color:#2060cc;background:rgba(66,133,244,.06);}\n.pill-rs{border-color:#ff9900;color:#cc7000;background:rgba(255,153,0,.06);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #14161e;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#3a3e4e;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#3ea8ff;border-color:#3ea8ff;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-style:italic;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3d4e;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.ch::before{background:var(--ch);}.db-card.dr::before{background:var(--dr);}.db-card.bq::before{background:var(--bq);}.db-card.rs::before{background:var(--rs);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-style:italic;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5870;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n.analogy{background:var(--ink);color:#c8ccd8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#4a4e5e;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d0d4e0;}\n.analogy-text strong{color:#3ea8ff;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-purple{background:var(--purple-bg);border-color:var(--purple);color:#2a1a4a;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8ccd8;border:1px solid #14161e;}\n.codeblock .c{color:#3a3e4e;}.codeblock .k{color:#3ea8ff;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8946a;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3d4e;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4858;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;font-style:italic;color:#f0f2fa;font-weight:400;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#4a4e5e;border:1px solid #2a2e3e;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3d4e;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-ch{background:var(--ch-bg);border-color:var(--ch);color:#c00;}.b-dr{background:var(--dr-bg);border-color:var(--dr);color:#1a70cc;}.b-bq{background:var(--bq-bg);border-color:var(--bq);color:#1a50cc;}.b-rs{background:var(--rs-bg);border-color:var(--rs);color:#cc7000;}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#3ea8ff;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3d4e;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#2a2e3e;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 OLAP Selection \u00b7 Manish-Almanac</div>\n    <h1>Choosing Your<br><em>OLAP Engine</em></h1>\n    <p class=\"hero-sub\">ClickHouse vs Apache Druid vs BigQuery vs Amazon Redshift \u2014 how to pick the right analytical database for every system design scenario, with real examples and every interview follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-ch\">ClickHouse</span>\n      <span class=\"db-pill pill-dr\">Apache Druid</span>\n      <span class=\"db-pill pill-bq\">BigQuery</span>\n      <span class=\"db-pill pill-rs\">Redshift</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#what\">What is OLAP?</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#internals\">How They Work</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"what\">\n  <div class=\"sec-tag\">00 \u00b7 The Foundation</div>\n  <h2>What is OLAP and why is it different?</h2>\n  <p>OLAP stands for <strong>Online Analytical Processing</strong>. It's the class of databases built for <em>reading a lot of data to answer complex questions</em>, as opposed to OLTP (Online Transaction Processing) databases which are built for <em>many small reads and writes</em>.</p>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">OLTP vs OLAP \u2014 the supermarket analogy</div>\n    <div class=\"analogy-text\">\n      <strong>OLTP (PostgreSQL, MySQL, DynamoDB):</strong> The cash register. Each transaction is tiny \u2014 scan item, charge card, update inventory. Thousands happening simultaneously. Each one must be fast and correct.<br><br>\n      <strong>OLAP (ClickHouse, BigQuery, Druid):</strong> The quarterly business review. The manager asks \"which products sold most in the North last Tuesday compared to the same Tuesday last year, broken down by hour?\" This query needs to scan millions of rows. No one expects it in 10ms \u2014 but they want it in under 2 seconds, not 2 hours.<br><br>\n      <strong>The core difference:</strong> OLTP is optimised for <strong>row access</strong> (get me order #12345). OLAP is optimised for <strong>column scans</strong> (sum all sales values in column X across 10 billion rows). This is why OLAP databases store data column-by-column instead of row-by-row.\n    </div>\n  </div>\n  <h3>Why Columnar Storage Changes Everything</h3>\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The Key Insight</div>\n    <p><strong>Row storage (PostgreSQL):</strong> Each row is stored together on disk. To compute <code>SUM(revenue)</code> across 1 billion rows, you read ALL columns of ALL rows \u2014 most of which you don't need.</p>\n    <p><strong>Column storage (ClickHouse/BigQuery):</strong> Each column is stored together. To compute <code>SUM(revenue)</code>, you only read the revenue column. 10x\u2013100x less data read. And integers in the same column compress 10\u201320x better than mixed row data.</p>\n    <p><strong>Real impact:</strong> A query that takes 10 minutes in PostgreSQL takes 300ms in ClickHouse \u2014 on the same data.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four OLAP Engines</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card ch\">\n      <div class=\"db-logo\">\ud83d\udd34</div>\n      <div class=\"db-name\">ClickHouse</div>\n      <div class=\"db-type\">Columnar OLAP \u00b7 Self-Hosted</div>\n      <div class=\"db-tagline\">The speed demon. Built by Yandex for web analytics. Ingests 500K rows/sec, answers GROUP BY on 100B rows in under 2 seconds. Battle-tested at Cloudflare, Uber, eBay. Self-host or ClickHouse Cloud.</div>\n      <div class=\"db-born\">Born 2016 \u00b7 Yandex \u2192 Apache \u00b7 MergeTree engine</div>\n    </div>\n    <div class=\"db-card dr\">\n      <div class=\"db-logo\">\ud83d\udd35</div>\n      <div class=\"db-name\">Apache Druid</div>\n      <div class=\"db-type\">Real-Time OLAP \u00b7 Self-Hosted</div>\n      <div class=\"db-tagline\">The sub-second explorer. Designed for interactive dashboards with &lt;1s query response. Pre-aggregates data at ingest time (rollup). Used by Lyft, Twitter, Netflix for operational analytics.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 Metamarkets \u2192 Apache \u00b7 Segment-based</div>\n    </div>\n    <div class=\"db-card bq\">\n      <div class=\"db-logo\">\ud83d\udd37</div>\n      <div class=\"db-name\">BigQuery</div>\n      <div class=\"db-type\">Serverless OLAP \u00b7 Managed GCP</div>\n      <div class=\"db-tagline\">The serverless giant. No clusters to manage. Pay per query. Scales to petabytes automatically. Perfect for data warehouses, data science teams, and ad-hoc exploration. Google's backbone for internal analytics.</div>\n      <div class=\"db-born\">Born 2010 \u00b7 Google \u00b7 Dremel paper lineage</div>\n    </div>\n    <div class=\"db-card rs\">\n      <div class=\"db-logo\">\ud83d\udfe0</div>\n      <div class=\"db-name\">Amazon Redshift</div>\n      <div class=\"db-type\">MPP Data Warehouse \u00b7 Managed AWS</div>\n      <div class=\"db-tagline\">The AWS native warehouse. Massive Parallel Processing (MPP), deep S3 integration (Redshift Spectrum), familiar SQL. Best for structured warehouse queries in the AWS ecosystem.</div>\n      <div class=\"db-born\">Born 2012 \u00b7 Amazon AWS \u00b7 ParAccel / PostgreSQL lineage</div>\n    </div>\n  </div>\n\n  <h3>How They Fundamentally Differ in Architecture</h3>\n  <div class=\"callout cl-purple\">\n    <div class=\"cl-lbl\">The Critical Architectural Distinction</div>\n    <p><strong>ClickHouse &amp; Druid:</strong> Shared-nothing architecture. Each node stores data and computes. Data is co-located with compute. Extremely fast for co-located queries. Hard to scale compute independently of storage.</p>\n    <p><strong>BigQuery &amp; Redshift Spectrum:</strong> Separate storage from compute. Data lives in object storage (GCS/S3). Compute scales independently. Slower for hot data but infinitely scalable and cheaper for cold data.</p>\n  </div>\n</section>\n\n<section id=\"internals\">\n  <div class=\"sec-tag\">02 \u00b7 Under the Hood</div>\n  <h2>How Each One Actually Works</h2>\n\n  <h3>ClickHouse \u2014 MergeTree Engine</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Parts</div><div class=\"concept-def\"><strong>Data is written as immutable sorted chunks called \"parts\".</strong> Each batch of INSERTs creates a new part on disk. No in-place updates \u2014 new parts are written, old ones merged in the background.<br><span style=\"color:#5a5848;font-size:12.5px;\">Why: immutable parts = no write locks = extremely fast concurrent writes at 500K rows/sec.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Background Merge</div><div class=\"concept-def\"><strong>Small parts are continuously merged into larger ones</strong> by a background process \u2014 like an LSM tree (similar to RocksDB or Cassandra's SSTables).<br><span style=\"color:#5a5848;font-size:12.5px;\">Why: keeps read performance high \u2014 fewer parts to open and scan per query.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">ORDER BY = Sort</div><div class=\"concept-def\"><strong>Data is physically sorted on disk by the ORDER BY key.</strong> A query filtering on <code>(entity_type, region, entity_id)</code> skips to the right block immediately.<br><code>ORDER BY (entity_type, region, entity_id, event_hour)</code><br><span style=\"color:#5a5848;font-size:12.5px;\">Effect: a filter on entity_type='video' AND region='IN' skips 99% of the file without reading it.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Sparse Index</div><div class=\"concept-def\"><strong>One index entry per 8,192 rows</strong> \u2014 tiny enough to fit entirely in RAM. Tells ClickHouse which disk block to start reading from.<br><span style=\"color:#5a5848;font-size:12.5px;\">No row-by-row index scan needed. Query jumps directly to the correct block on disk.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">LowCardinality</div><div class=\"concept-def\"><strong>Columns with few distinct values are dictionary-encoded as integers.</strong><br>\"video\" \u2192 1, \"hashtag\" \u2192 2. Stores integers instead of strings in every row.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 10x smaller storage. 10x faster string comparisons. Use for: entity_type, region, device.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partitioning</div><div class=\"concept-def\"><strong>Data is split into partitions by a partition key</strong> \u2014 usually date or month.<br><code>PARTITION BY toYYYYMM(event_date)</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Partition pruning: a query on today only reads today's partition. A year of history is 364/365 untouched.</span></div></div>\n</div>\n\n  <h3>Apache Druid \u2014 Pre-Aggregation at Ingest (Rollup)</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">What is Rollup?</div><div class=\"concept-def\"><strong>Druid pre-aggregates data at ingest time.</strong> Events sharing the same dimensions within the same time granularity are collapsed into a single aggregated row before writing to disk.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Result: 100M raw events \u2192 2M aggregated rows. 50x storage reduction.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Before Rollup</div><div class=\"concept-def\">100 million raw events, each stored individually:<br><code style=\"display:block;margin:4px 0;\">user_id=123, video_id=456, ts=14:23:45, region=IN</code><code style=\"display:block;margin:4px 0;\">user_id=789, video_id=456, ts=14:23:52, region=IN</code><span style=\"color:#5a5848;font-size:12.5px;\">847 different users watching the same video in the same minute.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">After Rollup</div><div class=\"concept-def\">2 million aggregated rows:<br><code style=\"display:block;margin:4px 0;\">video_id=456, minute=14:23, region=IN, <strong>count=847</strong></code><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 847 events collapsed into 1 row. The count query is already answered \u2014 no scanning needed.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">The Trade-off</div><div class=\"concept-def\"><strong>You permanently lose individual row detail.</strong> Can no longer answer \"how many unique users?\" unless you included a HyperLogLog sketch column at ingest time.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Rollup is irreversible. Choose your dimensions and time granularity carefully before going live.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">vs ClickHouse</div><div class=\"concept-def\">ClickHouse's AggregatingMergeTree aggregates <strong>in the background after ingest</strong> \u2014 stores full data initially, then merges. More flexible, but higher initial storage. Druid rollup is more aggressive: collapses at ingest, far less storage, less flexibility.</div></div>\n</div>\n\n  <h3>BigQuery \u2014 Dremel's Columnar Tree</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Dremel Tree</div><div class=\"concept-def\"><strong>BigQuery distributes your query across thousands of worker nodes in a tree.</strong> Root node splits your SQL into sub-tasks. Leaf nodes read columns from Google's Colossus storage in parallel. Thousands reading simultaneously = 1TB scanned in seconds.<br><span style=\"color:#5a5848;font-size:12.5px;\">You don't manage these workers \u2014 they spin up and down invisibly per query.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Cost Model</div><div class=\"concept-def\"><strong>You pay per byte scanned \u2014 not per compute time.</strong><br><span style=\"color:#b83030;font-size:12.5px;\">SELECT * FROM table \u2192 scans ALL columns \u2192 expensive</span><br><span style=\"color:#1a7a4a;font-size:12.5px;\">SELECT revenue FROM table \u2192 scans 1 column \u2192 cheap (~10x less)</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Rule: never SELECT * in BigQuery. Always specify only the columns you need.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partition Pruning</div><div class=\"concept-def\"><strong>Partition your table by date.</strong> A query with <code>WHERE event_date = '2026-03-20'</code> skips every other day's data entirely.<br><code>PARTITION BY DATE(event_time)</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A query on 1 year of data only scans 1/365th of the bytes.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Clustering</div><div class=\"concept-def\"><strong>Cluster by your most common filter columns.</strong> BigQuery co-locates rows with the same cluster values in the same physical block within each partition.<br><code>CLUSTER BY entity_type, region</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A filter on entity_type='video' AND region='IN' skips all other blocks. Combined with partitioning: 2000x less data scanned.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Slot Reservations</div><div class=\"concept-def\"><strong>For predictable, high-volume workloads: buy compute slots at flat rate.</strong> A slot = one unit of BigQuery compute. Buy 500 slots vs paying $5/TB per query.<br><span style=\"color:#5a5848;font-size:12.5px;\">Break-even: if you consistently scan &gt;20TB/day, flat-rate slots are cheaper than on-demand pricing.</span></div></div>\n</div>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">03 \u00b7 Full Comparison</div>\n  <h2>Every Dimension That Matters</h2>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>ClickHouse \ud83d\udd34</th><th>Druid \ud83d\udd35</th><th>BigQuery \ud83d\udd37</th><th>Redshift \ud83d\udfe0</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Architecture</td><td>Columnar, shared-nothing</td><td>Columnar, pre-aggregated segments</td><td>Serverless, storage-compute separated</td><td>MPP cluster, semi-managed</td></tr>\n      <tr><td class=\"row-head\">Ingest Speed</td><td><span class=\"good\">500K rows/sec</span> streaming</td><td><span class=\"good\">Streaming + batch</span> real-time rollup</td><td><span class=\"warn\">Batch primary</span> streaming via Pub/Sub</td><td><span class=\"warn\">Batch primary</span> COPY from S3</td></tr>\n      <tr><td class=\"row-head\">Query Latency</td><td><span class=\"good\">300ms\u20132s</span> on 100B rows</td><td><span class=\"good\">&lt;1s</span> interactive dashboards</td><td><span class=\"warn\">2\u201360s</span> depends on data scanned</td><td><span class=\"warn\">2\u201330s</span> for complex queries</td></tr>\n      <tr><td class=\"row-head\">Sub-Second Queries</td><td><span class=\"warn\">Yes for pre-sorted data</span></td><td><span class=\"good\">Yes \u2014 that's the whole point</span></td><td><span class=\"bad\">Rarely without caching</span></td><td><span class=\"bad\">No \u2014 MPP startup overhead</span></td></tr>\n      <tr><td class=\"row-head\">Storage Cost</td><td><span class=\"good\">Low</span> \u2014 self-hosted, great compression</td><td><span class=\"warn\">Medium</span> \u2014 segment overhead</td><td><span class=\"warn\">$0.02/GB/month</span> GCS</td><td><span class=\"warn\">$0.024/GB/month</span> Redshift storage</td></tr>\n      <tr><td class=\"row-head\">Compute Cost</td><td><span class=\"good\">Fixed</span> \u2014 you own the nodes</td><td><span class=\"good\">Fixed</span> \u2014 self-managed</td><td><span class=\"warn\">$5 per TB scanned</span></td><td><span class=\"warn\">Node-hours</span> even when idle</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"warn\">Medium</span> \u2014 manage nodes, merges</td><td><span class=\"bad\">High</span> \u2014 complex: Zookeeper, deep storage, etc.</td><td><span class=\"good\">Zero</span> \u2014 fully serverless</td><td><span class=\"warn\">Medium</span> \u2014 managed but not serverless</td></tr>\n      <tr><td class=\"row-head\">Scale Ceiling</td><td>Petabytes (sharded)</td><td>Petabytes</td><td><span class=\"good\">Truly unlimited</span></td><td>~Petabyte with RA3</td></tr>\n      <tr><td class=\"row-head\">SQL Compatibility</td><td>ClickHouse SQL (non-standard)</td><td>Druid SQL + native JSON</td><td>Standard SQL</td><td>PostgreSQL-compatible</td></tr>\n      <tr><td class=\"row-head\">Streaming Ingest</td><td><span class=\"good\">Native</span> Kafka engine</td><td><span class=\"good\">Native</span> real-time ingestion</td><td><span class=\"warn\">Via Dataflow/Pub/Sub</span></td><td><span class=\"bad\">Not native</span> \u2014 batch COPY</td></tr>\n      <tr><td class=\"row-head\">Cloud Lock-in</td><td><span class=\"good\">None</span> \u2014 open source</td><td><span class=\"good\">None</span> \u2014 open source</td><td><span class=\"bad\">GCP only</span></td><td><span class=\"bad\">AWS only</span></td></tr>\n      <tr><td class=\"row-head\">Best For</td><td>High-frequency event analytics</td><td>Sub-second operational dashboards</td><td>Ad-hoc exploration, data science</td><td>Structured DW in AWS ecosystem</td></tr>\n      <tr><td class=\"row-head\">Used By</td><td>Cloudflare, Uber, eBay</td><td>Lyft, Twitter, Netflix</td><td>Twitter, Spotify, The Trade Desk</td><td>NYSE, Yelp, McDonald's</td></tr>\n    </tbody>\n  </table>\n\n  <h3>Cost at Scale \u2014 Real Numbers</h3>\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">BigQuery vs ClickHouse at Top-K Scale</div>\n    <p>Assume: 500K events/sec \u2192 43B events/day \u2192 100 bytes per row after aggregation \u2192 ~4.3TB of aggregated data written per day. Analytical queries run 1,000 times/day each scanning ~500GB.</p>\n    <p><strong>BigQuery:</strong> 1,000 queries \u00d7 500GB \u00d7 $5/TB = <strong>$2,500/day</strong> in query costs alone. Plus storage: 4.3TB \u00d7 30 days \u00d7 $0.02 = $2,580/month.</p>\n    <p><strong>ClickHouse (10 nodes, 16-core, 64GB each, AWS r6i.4xlarge):</strong> 10 \u00d7 $1.00/hr \u00d7 24hr = <strong>$240/day</strong>. Handles all 1,000 queries easily. Same queries, same data, ~10x cheaper at this scale.</p>\n    <p><strong>BigQuery wins for:</strong> Unpredictable, bursty, data-science workloads where you'd otherwise pay for idle cluster capacity.</p>\n  </div>\n</section>\n\n<section id=\"examples\">\n  <div class=\"sec-tag\">04 \u00b7 Applied to Real Systems</div>\n  <h2>Which OLAP Engine for Which System?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">HIGH FREQUENCY \u00b7 500K EVENTS/SEC</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-ch\">ClickHouse \u2713</span> Flink flushes aggregated rows every 30s directly into ClickHouse via its Kafka engine. AggregatingMergeTree + columnar storage = \"top 10 videos in India last hour\" in 300ms on 100B rows. Streaming ingest is native \u2014 no extra pipeline.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT DRUID</div><div class=\"choice-val\"><span class=\"badge b-a\">Druid \u26a0</span> Druid's rollup would actually work well here \u2014 but the operational complexity (ZooKeeper, Historical nodes, Broker nodes, Coordinator, Overlord) is far higher than ClickHouse. For Top-K specifically, ClickHouse's window functions and GROUP BY are cleaner.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT BIGQUERY</div><div class=\"choice-val\"><span class=\"badge b-r\">BigQuery \u2717</span> At 43B writes/day, BigQuery Storage Write API costs would be significant. And the 2\u20135s query latency makes \"what's trending right now\" feel slow. ClickHouse is 10x cheaper and 10x faster for this specific workload.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">QUERIES ENABLED</div><div class=\"choice-val\">Historical Top-K (\"what was #1 last Tuesday?\") \u00b7 Trend analysis hour-over-hour \u00b7 Breakdown by device/region \u00b7 Rank history for a specific entity \u2014 all in &lt;2s.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ride-Sharing Analytics (Uber)</div>\n      <span class=\"sd-example-tag\">OPERATIONAL DASHBOARDS</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">REAL-TIME OPS</div><div class=\"choice-val\"><span class=\"badge b-dr\">Druid \u2713</span> Uber uses Druid for operational dashboards: \"How many rides completed in the last 5 minutes by city?\" Sub-second queries on streaming data let operations teams react in real time. Druid's rollup pre-aggregates by city+minute, making this near-instant.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">LONG-TERM ANALYTICS</div><div class=\"choice-val\"><span class=\"badge b-bq\">BigQuery \u2713</span> Historical analysis: \"Compare Q4 ride completion rates by city 2024 vs 2025.\" Petabytes of historical data, ad-hoc exploration by data scientists, no need for sub-second latency. BigQuery's serverless model is perfect \u2014 data scientists don't need to manage clusters.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Ad Analytics Platform</div>\n      <span class=\"sd-example-tag\">HIGH CARDINALITY \u00b7 REAL-TIME BILLING</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-ch\">ClickHouse \u2713</span> Ad click aggregation: entity_id, campaign_id, impression counts, CTR \u2014 high write throughput, complex GROUP BY queries, need accurate counts for billing. ClickHouse's exactly-once semantics via Kafka + ReplacingMergeTree prevents double-counting.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">WHY NOT DRUID</div><div class=\"choice-val\"><span class=\"badge b-r\">Druid \u2717</span> Druid's rollup loses individual event detail. For billing, you need exact click counts per ad per user. Rollup would lose the granularity needed for fraud detection and accurate billing.</div></div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Data Warehouse / Business Intelligence</div>\n      <span class=\"sd-example-tag\">AD-HOC \u00b7 DATA SCIENCE</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\"><div class=\"choice-label\">WINNER</div><div class=\"choice-val\"><span class=\"badge b-bq\">BigQuery \u2713</span> For a BI team running diverse queries across petabytes of historical data with unpredictable patterns, BigQuery's serverless model wins. No cluster to right-size, pay only for what you query. Connects natively to Looker, Tableau, dbt.</div></div>\n      <div class=\"choice-row\"><div class=\"choice-label\">AWS EQUIVALENT</div><div class=\"choice-val\"><span class=\"badge b-rs\">Redshift \u2713</span> Same use case but in the AWS ecosystem. Redshift Spectrum lets you query data directly in S3 without loading it. Deep integration with Glue, EMR, QuickSight. If you're all-in on AWS, Redshift + Spectrum is the natural choice.</div></div>\n    </div>\n  </div>\n</section>\n\n<section id=\"decision\">\n  <div class=\"sec-tag\">05 \u00b7 The Decision Framework</div>\n  <h2>How to Pick in an Interview</h2>\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick an OLAP Engine \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your query latency requirement?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">&lt;1s interactive \u2192</span><span class=\"opt-text\"><strong>Apache Druid.</strong> Pre-aggregation at ingest means most of the work is already done before the query arrives.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">1\u20135s analytical \u2192</span><span class=\"opt-text\"><strong>ClickHouse.</strong> Columnar MergeTree on sorted data returns GROUP BY results in 300ms\u20132s on 100B rows.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">5\u201360s ad-hoc \u2192</span><span class=\"opt-text\"><strong>BigQuery or Redshift.</strong> Serverless/MPP \u2014 accepts higher latency in exchange for unlimited scale and zero ops.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your ingest pattern?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Streaming (Kafka) \u2192</span><span class=\"opt-text\"><strong>ClickHouse</strong> (native Kafka engine, 500K rows/sec) or <strong>Druid</strong> (streaming ingestion with rollup).</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Batch loads \u2192</span><span class=\"opt-text\"><strong>BigQuery</strong> (batch load API, free) or <strong>Redshift</strong> (COPY from S3).</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need exact counts, or are approximations OK?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Exact (billing) \u2192</span><span class=\"opt-text\"><strong>ClickHouse or BigQuery.</strong> No rollup \u2014 every raw row is stored and counted precisely.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Approx OK \u2192</span><span class=\"opt-text\"><strong>Druid with rollup + HyperLogLog.</strong> 50x storage reduction; accepts \u00b10.1% count error.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">What are your ops constraints?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Small team \u2192</span><span class=\"opt-text\"><strong>BigQuery</strong> (fully serverless) or <strong>Redshift</strong> (managed). No nodes to manage.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Infra capacity \u2192</span><span class=\"opt-text\"><strong>ClickHouse or Druid.</strong> Self-hosted on commodity hardware. 10x cheaper at extreme scale.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n      <div class=\"step-q\">Cloud commitment?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Agnostic \u2192</span><span class=\"opt-text\"><strong>ClickHouse or Druid.</strong> Open source, runs anywhere.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">GCP \u2192</span><span class=\"opt-text\"><strong>BigQuery.</strong> Native GCS, Looker, Vertex AI integration.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">AWS \u2192</span><span class=\"opt-text\"><strong>Redshift.</strong> Deep S3/Glue/EMR/QuickSight integration.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#c00\">\ud83d\udd34 ClickHouse is perfect for\u2026</div>\n      <ul><li>High-frequency event analytics (Top-K, ad clicks)</li><li>Need streaming ingest + fast queries</li><li>Self-managed, cost-sensitive at scale</li><li>Time-series with complex aggregations</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#1a70cc\">\ud83d\udd35 Druid is perfect for\u2026</div>\n      <ul><li>Sub-second operational dashboards</li><li>High-cardinality dimensions (millions of unique values)</li><li>Pre-aggregation acceptable (approx counts ok)</li><li>Real-time + historical unified queries</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#1a50cc\">\ud83d\udd37 BigQuery is perfect for\u2026</div>\n      <ul><li>Petabyte-scale data warehouse</li><li>Data science, ML training data, ad-hoc</li><li>Bursty, unpredictable query patterns</li><li>Team without infra/ops capacity</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc7000\">\ud83d\udfe0 Redshift is perfect for\u2026</div>\n      <ul><li>Structured ETL pipelines in AWS</li><li>Traditional BI/reporting workloads</li><li>Deep integration with AWS ecosystem</li><li>Familiar PostgreSQL-compatible SQL</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">06 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why can't I just use PostgreSQL for analytics? It has window functions and GROUP BY.<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>You can \u2014 until you can't.</strong> PostgreSQL is fine for analytics up to ~100GB and simple aggregations. But at billions of rows, a single <code>GROUP BY</code> on PostgreSQL requires a full sequential scan reading every column. ClickHouse on the same data reads only the columns you reference, compresses integers 10\u201320x, and parallelises across all CPU cores.<br><br>Benchmark: <code>SELECT entity_type, SUM(view_count) FROM events WHERE event_date = today() GROUP BY entity_type</code> \u2014 PostgreSQL on 1B rows: ~8 minutes. ClickHouse: ~400ms. Same query, same data. That's why OLAP exists.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">ClickHouse says it can ingest 500K rows/sec. How does that work with Kafka?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>ClickHouse has a native Kafka engine \u2014 you define a Kafka table and ClickHouse becomes a consumer.</strong><br><br><code>CREATE TABLE kafka_events ENGINE = Kafka SETTINGS kafka_broker_list = 'kafka:9092', kafka_topic_list = 'events', kafka_format = 'JSONEachRow';</code><br><br>Then a Materialized View continuously reads from the Kafka table and inserts into your main MergeTree table. ClickHouse batches these inserts internally \u2014 it doesn't write each message individually. Batches of thousands of rows are written as a single \"part\" to disk, keeping write amplification low. The result: Kafka \u2192 ClickHouse pipeline with 30-60 second latency and 500K rows/sec throughput.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between Druid's rollup and ClickHouse's AggregatingMergeTree?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Both pre-aggregate \u2014 but at different points in the pipeline and with different flexibility.</strong><br><br><strong>Druid rollup</strong> happens at ingest time. Raw events with the same dimensions within the same time granularity are collapsed into a single aggregate row. You define rollup at table creation. If you didn't include a dimension at ingest, you can never query by it. This achieves 50\u2013100x storage reduction but is irreversible.<br><br><strong>ClickHouse AggregatingMergeTree</strong> aggregates during background merge. Raw data is initially stored, then merged and aggregated in the background. You keep the full resolution until merged. More flexible, but storage reduction comes later and is less extreme than Druid's rollup.<br><br><strong>The choice:</strong> Known, fixed query patterns with approximate counts OK \u2192 Druid rollup. Need full granularity or exact counts \u2192 ClickHouse AggregatingMergeTree.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">BigQuery charges per TB scanned. How do you control costs in a large team?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Four cost control techniques used at production scale:</strong><br><br><strong>1. Partition pruning:</strong> Always filter on the partition column (usually date). <code>WHERE event_date = '2026-03-20'</code> scans only one day's partition instead of all-time data. Mandatory in every query policy.<br><br><strong>2. Column selection:</strong> Never <code>SELECT *</code>. Each column selected costs proportional to its size. <code>SELECT event_type, COUNT(*)</code> is 10x cheaper than <code>SELECT *</code> on the same rows.<br><br><strong>3. Clustering:</strong> Cluster tables by high-cardinality filter columns. BigQuery skips irrelevant blocks within a partition when the filter matches a clustered column.<br><br><strong>4. Materialized Views / cached results:</strong> Common dashboard queries are cached for 24 hours. BigQuery caches identical queries automatically at no cost. Materialised Views pre-compute and store expensive aggregations.<br><br><strong>5. Reservations:</strong> Buy BigQuery slots (fixed compute) for predictable workloads instead of paying per query.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">In the Top-K system, why is ClickHouse used instead of Cassandra for analytics?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Cassandra and ClickHouse serve fundamentally different query profiles.</strong><br><br><strong>Cassandra (warm store in Top-K):</strong> \"Give me all hourly counts for entity X in region IN over the last 30 days\" \u2014 a narrow range scan within one partition. Fast because it reads very little data. Good for: backfilling Redis, known entity lookups.<br><br><strong>ClickHouse (OLAP layer in Top-K):</strong> \"Give me the top 10 entities globally across all regions for the last 7 days, broken down by device, with hour-over-hour change\" \u2014 a full table scan across billions of rows with complex aggregation. Cassandra would do a full cluster scan for this query \u2014 every node would need to respond. ClickHouse scans only relevant columns and returns the answer in 500ms.<br><br><strong>Rule of thumb:</strong> Cassandra is for \"fetch a specific partition.\" ClickHouse is for \"aggregate across many partitions.\" They're complementary, not competitive.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">OLAP \u00b7 CLICKHOUSE \u00b7 DRUID \u00b7 BIGQUERY \u00b7 REDSHIFT \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Analytics DB' },
  streaming:   { title: 'Stream Processing Decoded',     srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>Stream Processing Showdown: Kafka vs Flink vs Kinesis vs Spark Streaming</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Sora:wght@300;400;600;700;800&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{--ink:#080c14;--page:#f2f4f8;--surface:#e6eaf2;--surface2:#d8dcec;--border:#c8cdd8;--muted:#687088;\n--kf:#000000;--kf-bg:#f0f0f0;--fl:#e35400;--fl-bg:#fff4ef;--ki:#ff9900;--ki-bg:#fff8ee;--ss:#e25100;--ss-bg:#fff3ee;\n--red:#c0392b;--red-bg:#fdf0ee;--green:#1a7a4a;--green-bg:#edf8f2;--amber:#b8720a;--amber-bg:#fdf6e8;--blue:#1a4f8a;--blue-bg:#edf2fb;--teal:#0a7070;--teal-bg:#edf6f6;\n--mono:'JetBrains Mono',monospace;--sans:'Sora',sans-serif;}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#dde0ec;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(90deg,transparent,transparent 80px,rgba(255,255,255,.008) 80px,rgba(255,255,255,.008) 81px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#3a3e50;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--sans);font-size:clamp(30px,5vw,56px);font-weight:800;line-height:1.05;letter-spacing:-1.5px;margin-bottom:20px;color:#eef0f8;}\nh1 em{color:#f77f3a;font-style:normal;}\n.hero-sub{font-size:15px;color:#5a5e70;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-kf{border-color:#666;color:#666;background:rgba(0,0,0,.05);}\n.pill-fl{border-color:#e35400;color:#c04400;background:rgba(227,84,0,.06);}\n.pill-ki{border-color:#ff9900;color:#cc7000;background:rgba(255,153,0,.06);}\n.pill-ss{border-color:#e25100;color:#b04000;background:rgba(226,81,0,.06);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #101420;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#2a2e40;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#f77f3a;border-color:#f77f3a;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:#7a7e90;margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--sans);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;letter-spacing:-.5px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\np{color:#3a3d50;font-size:14.5px;margin-bottom:12px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.kf::before{background:#333;}.db-card.fl::before{background:var(--fl);}.db-card.ki::before{background:var(--ki);}.db-card.ss::before{background:var(--ss);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--sans);font-size:17px;font-weight:700;letter-spacing:-.3px;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#7a7e90;margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5e70;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:#7a7e90;margin-top:8px;}\n.role-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:24px 0;}\n.role-card{border-radius:8px;padding:20px;border:1px solid var(--border);}\n.role-card.transport{background:#f8f0e8;border-color:#d8b88a;}\n.role-card.processing{background:#e8f4f0;border-color:#8ac8b0;}\n.role-title{font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;margin-bottom:8px;font-weight:600;}\n.role-body{font-size:13.5px;color:#3a3d50;line-height:1.65;}\n.analogy{background:var(--ink);color:#c8ccd8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#3a3e50;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d0d4e0;}\n.analogy-text strong{color:#f77f3a;}\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-teal{background:var(--teal-bg);border-color:var(--teal);color:#0a2a2a;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n.codeblock{background:var(--ink);border-radius:6px;padding:20px 22px;font-family:var(--mono);font-size:11.5px;line-height:2;overflow-x:auto;margin:14px 0;color:#c8ccd8;border:1px solid #101420;}\n.codeblock .c{color:#2a2e40;}.codeblock .k{color:#f77f3a;}.codeblock .s{color:#8bc4a0;}.codeblock .n{color:#e8a06a;}.codeblock .g{color:#a8d878;}.codeblock .r{color:#e87878;}.codeblock .t{color:#7ab8e0;}\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:#7a7e90;}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3d50;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--sans);font-size:16px;font-weight:700;color:#eef0f8;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#3a3e50;border:1px solid #1a1e30;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#7a7e90;width:120px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3d50;line-height:1.6;}\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-kf{background:#f0f0f0;border-color:#999;color:#444;}.b-fl{background:var(--fl-bg);border-color:var(--fl);color:#c04400;}.b-ki{background:var(--ki-bg);border-color:var(--ki);color:#cc7000;}.b-ss{background:var(--ss-bg);border-color:var(--ss);color:#b04000;}.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#f77f3a;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3d50;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4e60;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#1a1e30;letter-spacing:2px;}\n\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:120px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n@media(max-width:560px){.concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}.opt-arrow{min-width:80px;}}\n\n</style>\n</head>\n<body>\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 Stream Processing \u00b7 Manish-Almanac</div>\n    <h1>Stream Processing<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">Kafka vs Apache Flink vs Amazon Kinesis vs Spark Streaming \u2014 understand the roles, the differences, and exactly how to use each in a FAANG-level system design interview. With real examples and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-kf\">Apache Kafka</span>\n      <span class=\"db-pill pill-fl\">Apache Flink</span>\n      <span class=\"db-pill pill-ki\">Amazon Kinesis</span>\n      <span class=\"db-pill pill-ss\">Spark Streaming</span>\n    </div>\n  </div>\n</div>\n<nav class=\"nav\">\n  <a href=\"#roles\">Transport vs Processing</a>\n  <a href=\"#identity\">Identity</a>\n  <a href=\"#kafka-deep\">Kafka Deep</a>\n  <a href=\"#processing\">Processing Engines</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n<div class=\"wrap\">\n\n<section id=\"roles\">\n  <div class=\"sec-tag\">00 \u00b7 The Critical Distinction</div>\n  <h2>Transport vs Processing \u2014 they're not the same thing</h2>\n  <p>The biggest mistake candidates make is treating Kafka, Flink, Kinesis, and Spark Streaming as competing alternatives. <strong>They're not.</strong> They play fundamentally different roles in a streaming architecture.</p>\n  <div class=\"role-grid\">\n    <div class=\"role-card transport\">\n      <div class=\"role-title\" style=\"color:#8a6020\">\ud83d\ude8c Transport / Message Bus</div>\n      <div class=\"role-body\"><strong>Kafka, Kinesis, Pulsar</strong><br><br>Like a highway \u2014 vehicles (messages) enter, travel through, and exit. The highway stores vehicles temporarily so producers don't have to wait for consumers to be ready. It decouples producers from consumers.<br><br>Key properties: durable storage, ordered delivery within partition, multiple consumers reading the same message independently, replay old messages.</div>\n    </div>\n    <div class=\"role-card processing\">\n      <div class=\"role-title\" style=\"color:#1a6a4a\">\u2699\ufe0f Stream Processor</div>\n      <div class=\"role-body\"><strong>Flink, Spark Streaming, Kafka Streams</strong><br><br>Like a factory that processes vehicles as they pass through \u2014 counting them, sorting them, combining them with data from other sources, detecting anomalies. The processor does the actual computation.<br><br>Key properties: stateful computation, windowing (tumbling, sliding, session), joins across streams, exactly-once semantics, fault tolerance with checkpoints.</div>\n    </div>\n  </div>\n  <div class=\"callout cl-teal\">\n    <div class=\"cl-lbl\">The correct mental model for Top-K</div>\n    <p><strong>Kafka</strong> = the highway. Events from users flow in, get durably stored, and multiple consumers can read them independently and at their own pace.</p>\n    <p><strong>Flink</strong> = the factory. Consumes from Kafka, applies the Count-Min Sketch, maintains the local heap, and every 30 seconds flushes the Top-K results to Redis and Cassandra.</p>\n    <p>You <strong>always use a transport layer AND a processing layer</strong> together. They're complementary, not competitive.</p>\n  </div>\n</section>\n\n<section id=\"identity\">\n  <div class=\"sec-tag\">01 \u00b7 Who Are They</div>\n  <h2>The Four Technologies</h2>\n  <div class=\"db-grid\">\n    <div class=\"db-card kf\">\n      <div class=\"db-logo\">\u2b1b</div>\n      <div class=\"db-name\">Apache Kafka</div>\n      <div class=\"db-type\">Distributed Message Bus</div>\n      <div class=\"db-tagline\">The gold standard for event streaming. Durable, ordered, replayable. Processes trillions of events/day at LinkedIn, Netflix, Uber. The backbone of nearly every modern data platform.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 LinkedIn \u2192 Apache \u00b7 Log-structured storage</div>\n    </div>\n    <div class=\"db-card fl\">\n      <div class=\"db-logo\">\ud83d\udd36</div>\n      <div class=\"db-name\">Apache Flink</div>\n      <div class=\"db-type\">Stateful Stream Processor</div>\n      <div class=\"db-tagline\">The stream processing heavyweight. True streaming (not micro-batch), exactly-once semantics, millisecond latency, complex windowing, stateful operations. Used by Uber, Alibaba, Apple for real-time pipelines.</div>\n      <div class=\"db-born\">Born 2014 \u00b7 TU Berlin \u2192 Apache \u00b7 Dataflow model</div>\n    </div>\n    <div class=\"db-card ki\">\n      <div class=\"db-logo\">\ud83d\udfe0</div>\n      <div class=\"db-name\">Amazon Kinesis</div>\n      <div class=\"db-type\">Managed Event Streaming (AWS)</div>\n      <div class=\"db-tagline\">Kafka's managed AWS alternative. Zero ops, auto-scaling shards, deep AWS integration (Lambda, S3, Redshift). Perfect if you're all-in AWS and don't want to manage a Kafka cluster.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 Amazon AWS \u00b7 Shard-based partitioning</div>\n    </div>\n    <div class=\"db-card ss\">\n      <div class=\"db-logo\">\u2726</div>\n      <div class=\"db-name\">Spark Streaming</div>\n      <div class=\"db-type\">Micro-Batch Stream Processor</div>\n      <div class=\"db-tagline\">Streaming built on Spark's batch engine. Uses micro-batches (seconds) rather than true streaming. Best when you already use Spark for batch ETL and want a unified pipeline. Not ideal for millisecond-latency requirements.</div>\n      <div class=\"db-born\">Born 2013 \u00b7 UC Berkeley \u2192 Apache \u00b7 Micro-batch model</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"kafka-deep\">\n  <div class=\"sec-tag\">02 \u00b7 Transport Layer Deep Dive</div>\n  <h2>Kafka \u2014 Understanding It at Interview Depth</h2>\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">Kafka explained for a complete layman</div>\n    <div class=\"analogy-text\">\n      Imagine a newspaper printing plant. Every morning, thousands of reporters (producers) submit stories. The plant prints millions of copies (events) and distributes them to hundreds of newsstands (partitions). Each newsstand keeps its newspapers for 7 days (retention).<br><br>\n      Any reader (consumer) can pick up a paper from any newsstand, and two readers picking up the same paper both get the full content \u2014 the paper isn't destroyed when read. A reader can also go back and re-read papers from last Tuesday (replay).<br><br>\n      <strong>The magic:</strong> Reporters don't wait for readers. Readers don't wait for reporters. The newsstand (Kafka) acts as a durable buffer between them.\n    </div>\n  </div>\n\n  <h3>The Core Kafka Concepts Every Interviewer Expects</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Topic</div><div class=\"concept-def\"><strong>A named, ordered stream of events.</strong> Like a table in a database but append-only.<br><code>\"user-clicks\"</code>, <code>\"video-views\"</code>, <code>\"payment-events\"</code><br><span style=\"color:#5a5848;font-size:12.5px;\">Producers write to a topic. Consumers read from a topic. They never interact directly \u2014 Kafka decouples them.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Partition</div><div class=\"concept-def\"><strong>A topic is split into N ordered partitions for parallelism.</strong> Each event is assigned based on its key:<br><code>partition = hash(entity_id) % N</code><br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Within a partition: order is GUARANTEED.</span> <span style=\"color:#b83030;font-size:12.5px;\">\u2717 Across partitions: NOT guaranteed.</span><br><span style=\"color:#5a5848;font-size:12.5px;\">Partitioning by entity_id means all events for video_123 go to the same partition \u2192 same Flink worker \u2192 no coordination needed.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Offset</div><div class=\"concept-def\"><strong>A sequential integer ID for each event within a partition.</strong> Consumers track their own position \u2014 \"I have read up to message #12,847\".<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Enables replay: if Flink crashes, it restarts from offset #12,847. Kafka still has all the events (7-day retention).</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Consumer Group</div><div class=\"concept-def\"><strong>A set of consumers sharing work on a topic.</strong> Each partition is consumed by exactly ONE consumer in the group. Multiple groups can read the same topic simultaneously and independently.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Flink, ClickHouse Kafka engine, and S3 sink can all read the same topic at the same time \u2014 each at their own pace, each with their own offset.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Broker</div><div class=\"concept-def\"><strong>A Kafka server node.</strong> Usually 3\u20135 brokers in production. Each partition is replicated across brokers (replication factor = 3).<br><span style=\"color:#5a5848;font-size:12.5px;\">Leader broker accepts writes. Followers replicate. If leader fails, a follower is promoted automatically \u2014 no downtime.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Retention</div><div class=\"concept-def\"><strong>How long Kafka stores events before deleting.</strong> Default 7 days. Configurable to forever.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This is what makes replay possible. Flink crashed? Kafka still has 7 days of events. Resume from last checkpoint offset \u2014 no data loss.</span></div></div>\n</div>\n\n  <h3>Kafka vs Kinesis \u2014 The Managed vs Self-Managed Decision</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Kafka \u2b1b</th><th>Amazon Kinesis \ud83d\udfe0</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Throughput</td><td><span class=\"good\">Millions/sec</span> per cluster</td><td><span class=\"warn\">1MB/sec or 1000 records/sec</span> per shard</td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Sub-millisecond</span></td><td><span class=\"warn\">70\u2013200ms</span> typical</td></tr>\n      <tr><td class=\"row-head\">Retention</td><td><span class=\"good\">Configurable</span> \u2014 days to forever</td><td><span class=\"warn\">24h default</span>, max 7 days (Kinesis Firehose: unlimited)</td></tr>\n      <tr><td class=\"row-head\">Replay</td><td><span class=\"good\">Any offset, any time</span></td><td><span class=\"warn\">Within retention window</span> only</td></tr>\n      <tr><td class=\"row-head\">Partitioning</td><td>Topics \u2192 Partitions (flexible count)</td><td>Streams \u2192 Shards (auto-scaling available)</td></tr>\n      <tr><td class=\"row-head\">Consumer Groups</td><td><span class=\"good\">Unlimited</span> independent consumer groups</td><td><span class=\"warn\">Limited</span> \u2014 5 consumers per shard by default</td></tr>\n      <tr><td class=\"row-head\">Ops Burden</td><td><span class=\"bad\">High</span> \u2014 manage brokers, ZK/KRaft, rebalancing</td><td><span class=\"good\">Zero</span> \u2014 fully managed</td></tr>\n      <tr><td class=\"row-head\">Cost Model</td><td>Fixed infra cost (predictable at scale)</td><td>Pay per shard-hour + data volume</td></tr>\n      <tr><td class=\"row-head\">Cloud Lock-in</td><td><span class=\"good\">None</span> \u2014 open source, any cloud</td><td><span class=\"bad\">AWS only</span></td></tr>\n      <tr><td class=\"row-head\">AWS Integration</td><td>Manual connectors</td><td><span class=\"good\">Native</span> Lambda triggers, S3 Firehose, Redshift</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"processing\">\n  <div class=\"sec-tag\">03 \u00b7 Processing Layer Deep Dive</div>\n  <h2>Flink vs Spark Streaming \u2014 True Streaming vs Micro-Batch</h2>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The Core Difference</div>\n    <p><strong>Apache Flink:</strong> True streaming. Processes each event as it arrives. State is maintained in memory/RocksDB between events. Latency: milliseconds. Results are continuously updated.</p>\n    <p><strong>Spark Streaming (Structured Streaming):</strong> Micro-batch. Collects events for X seconds (e.g., 5s), then processes the batch. Latency: minimum is the batch interval. Simpler programming model, reuses Spark's batch optimisations.</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">True streaming vs micro-batch \u2014 the toll booth analogy</div>\n    <div class=\"analogy-text\">\n      <strong>True streaming (Flink):</strong> Each car approaches the toll booth and is processed individually as it arrives. The attendant collects, processes, and lets through each car without waiting. Immediate, real-time.<br><br>\n      <strong>Micro-batch (Spark Streaming):</strong> Cars are held at a red light for 5 seconds. Then the light turns green, all cars are processed together as a batch, then the light turns red again. Slightly delayed but can be more efficient for high volumes.\n    </div>\n  </div>\n\n  <h3>Flink's Key Capabilities \u2014 What Makes It the FAANG Choice</h3>\n  <div class=\"concept-grid\">\n  <div class=\"concept-row\"><div class=\"concept-term\">Tumbling Window</div><div class=\"concept-def\"><strong>Fixed-size, non-overlapping time buckets.</strong> Events from t=0 to t=30s form one window. At t=30s: window closes, results emitted, new window starts from scratch.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">Used in Top-K: flush Top-K results to Redis + Cassandra every 30 seconds. Simple, low memory, predictable cost.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Sliding Window</div><div class=\"concept-def\"><strong>Overlapping windows \u2014 span Y, slide every X.</strong> A 1-hour window sliding every 5 minutes keeps 12 overlapping windows active simultaneously.<br><span style=\"color:#5a5848;font-size:12.5px;\">Used for: \"trending in the last hour\" with smooth continuous updates. Cost: 12\u00d7 the memory and compute of a tumbling window.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Session Window</div><div class=\"concept-def\"><strong>Window stays open while user is active, closes after an idle gap.</strong> Gap timeout = 30 minutes: session ends after 30 min of inactivity.<br><span style=\"color:#5a5848;font-size:12.5px;\">Used for: user session analytics, funnel analysis, engagement time measurement.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Exactly-Once</div><div class=\"concept-def\"><strong>Each event is counted exactly once even if Flink crashes and restarts.</strong><br>Every 60s: Flink saves its full state (Count-Min Sketch, heap, Bloom filter) + last Kafka offset to S3. On crash: restore state from S3, resume reading Kafka from saved offset.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">Two-phase commit: Flink only confirms the offset to Kafka AFTER the S3 checkpoint completes. No event lost or double-counted.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">RocksDB State</div><div class=\"concept-def\"><strong>Flink state can be larger than available RAM.</strong> RocksDB spills to local disk, keeping only hot entries in memory. Checkpointed to S3 for fault tolerance.<br><span style=\"color:#5a5848;font-size:12.5px;\">In Top-K: the Count-Min Sketch (~6KB) and local min-heap ARE Flink state. They survive restarts because they're in the checkpoint.</span></div></div>\n  <div class=\"concept-row\"><div class=\"concept-term\">Watermarks</div><div class=\"concept-def\"><strong>Flink's mechanism for handling late-arriving events.</strong> A watermark at t=14:24:00 signals \"all events before 14:24:00 have probably arrived.\" Windows only close when the watermark passes the window end.<br><span style=\"color:#5a5848;font-size:12.5px;\">Allowed lateness: after a window closes, Flink waits X more seconds for stragglers. Late events re-trigger the window with a corrected result.</span></div></div>\n</div>\n\n  <h3>When to Use Each Processing Engine</h3>\n  <table class=\"comp-table\">\n    <thead><tr><th>Dimension</th><th>Apache Flink \ud83d\udd36</th><th>Spark Streaming \u2726</th><th>Kafka Streams</th></tr></thead>\n    <tbody>\n      <tr><td class=\"row-head\">Processing Model</td><td><span class=\"good\">True streaming</span></td><td><span class=\"warn\">Micro-batch</span> (1\u201310s)</td><td><span class=\"good\">True streaming</span></td></tr>\n      <tr><td class=\"row-head\">Latency</td><td><span class=\"good\">Milliseconds</span></td><td><span class=\"warn\">Seconds</span> (batch interval)</td><td><span class=\"good\">Milliseconds</span></td></tr>\n      <tr><td class=\"row-head\">Exactly-Once</td><td><span class=\"good\">Yes</span> \u2014 native</td><td><span class=\"warn\">Yes</span> \u2014 with idempotent sinks</td><td><span class=\"good\">Yes</span> \u2014 within Kafka</td></tr>\n      <tr><td class=\"row-head\">Complexity</td><td><span class=\"warn\">High</span> \u2014 dedicated cluster</td><td><span class=\"warn\">Medium</span> \u2014 reuses Spark</td><td><span class=\"good\">Low</span> \u2014 library, no cluster</td></tr>\n      <tr><td class=\"row-head\">State Management</td><td><span class=\"good\">RocksDB</span>, large state ok</td><td><span class=\"warn\">In-memory</span> \u2014 limited state</td><td><span class=\"good\">RocksDB</span> local to app</td></tr>\n      <tr><td class=\"row-head\">Best For</td><td>Complex stateful streaming, low latency</td><td>Already using Spark batch; simple streaming</td><td>Lightweight per-service streaming</td></tr>\n      <tr><td class=\"row-head\">Throughput</td><td>Millions events/sec</td><td>Millions events/sec (in batch)</td><td>Hundreds K/sec per app</td></tr>\n      <tr><td class=\"row-head\">Used By</td><td>Uber, Alibaba, Apple, Netflix</td><td>Databricks customers, Spark shops</td><td>Microservice architectures</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"comparison\">\n  <div class=\"sec-tag\">04 \u00b7 The Full Stack</div>\n  <h2>How They Combine in a Real Architecture</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">The standard streaming stack pattern</div>\n    <p><strong>Layer 1 \u2014 Producers:</strong> Applications, services, IoT sensors emit events.</p>\n    <p><strong>Layer 2 \u2014 Transport (Kafka / Kinesis):</strong> Events are durably stored, decoupling producers from consumers. Multiple downstream consumers read independently.</p>\n    <p><strong>Layer 3 \u2014 Stream Processor (Flink / Spark):</strong> Consumes from transport layer, applies business logic (windowing, aggregation, enrichment, filtering), outputs results.</p>\n    <p><strong>Layer 4 \u2014 Sinks:</strong> Results written to Redis (hot), Cassandra (warm), ClickHouse (analytics), S3 (cold/archive).</p>\n  </div>\n\n  <div class=\"step-block\">\n  <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>How to Pick Streaming Technology \u2014 Ask in Order</div>\n  <div class=\"step-block-body\">\n    <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n      <div class=\"step-q\">What is your latency requirement?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Sub-second \u2192</span><span class=\"opt-text\"><strong>Kafka + Flink.</strong> True streaming \u2014 each event processed in milliseconds. Required for fraud detection, real-time alerts, live scoring.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Seconds OK \u2192</span><span class=\"opt-text\"><strong>Kafka + Flink or Kafka + Spark Streaming.</strong> Either works. Flink is cleaner; Spark if you already have it running.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Minutes OK \u2192</span><span class=\"opt-text\"><strong>Kafka/Kinesis + Spark Structured Streaming.</strong> Micro-batch ETL into data warehouse. Simple, proven, cost-effective.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n      <div class=\"step-q\">Do you need stateful computation?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>Flink.</strong> Best-in-class: RocksDB state backend survives restarts, scales beyond RAM, checkpoints to S3. Running counts, windowed aggregations, per-user history.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>Kafka Streams</strong> (library, no cluster) or <strong>Kinesis Data Analytics.</strong> Simple filter, transform, route without managing state.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n      <div class=\"step-q\">Transport: managed cloud or self-hosted?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">AWS, zero ops \u2192</span><span class=\"opt-text\"><strong>Amazon Kinesis.</strong> Auto-scaling shards, Lambda triggers, Firehose to S3/Redshift. No brokers to manage.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">High throughput \u2192</span><span class=\"opt-text\"><strong>Apache Kafka.</strong> Millions/sec per cluster. 7-day replay. Multiple independent consumer groups. Cheaper at scale.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">GCP / Azure \u2192</span><span class=\"opt-text\"><strong>Google Pub/Sub</strong> or <strong>Azure Event Hubs</strong> \u2014 cloud-native equivalents of Kinesis.</span></div>\n      </div>\n    </div></div>\n    <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n      <div class=\"step-q\">Processing: team expertise?</div>\n      <div class=\"step-options\">\n        <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Already use Spark \u2192</span><span class=\"opt-text\"><strong>Spark Structured Streaming.</strong> Same API, same cluster, unified batch + streaming codebase. No new technology to learn.</span></div>\n        <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Low-latency + state \u2192</span><span class=\"opt-text\"><strong>Apache Flink.</strong> Industry standard for stateful streaming at FAANG scale. Uber, Apple, Alibaba all use it.</span></div>\n        <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Simple, per-service \u2192</span><span class=\"opt-text\"><strong>Kafka Streams.</strong> A library \u2014 runs inside your service process. No separate cluster. Perfect for microservices.</span></div>\n      </div>\n    </div></div>\n  </div>\n</div>\n\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#444\">\u2b1b Use Kafka when\u2026</div>\n      <ul><li>High throughput (&gt;100K/sec per topic)</li><li>Long retention / replay needed</li><li>Multiple independent consumers</li><li>Not locked into AWS</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#c04400\">\ud83d\udd36 Use Flink when\u2026</div>\n      <ul><li>Sub-second latency needed</li><li>Complex stateful operations</li><li>Windowed aggregations</li><li>Exactly-once critical (fraud, billing)</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#cc7000\">\ud83d\udfe0 Use Kinesis when\u2026</div>\n      <ul><li>AWS-native, zero ops priority</li><li>Moderate throughput</li><li>Lambda integration needed</li><li>Firehose delivery to S3/Redshift</li></ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:#b04000\">\u2726 Use Spark Streaming when\u2026</div>\n      <ul><li>Already have Spark infrastructure</li><li>ETL/data warehouse loading</li><li>Unified batch + streaming code</li><li>Seconds latency is acceptable</li></ul>\n    </div>\n  </div>\n</section>\n\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every Hard Follow-up, Answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Kafka guarantees at-most-once, at-least-once, or exactly-once?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>All three \u2014 depending on how you configure it.</strong><br><br><strong>At-most-once:</strong> Consumer reads message, immediately commits offset, then processes. If processing crashes, the message is lost (offset already advanced).<br><br><strong>At-least-once:</strong> Consumer reads, processes, then commits offset. If processing crashes before commit, message is reprocessed on restart. May be processed twice.<br><br><strong>Exactly-once (EOS):</strong> Requires both idempotent producers (enable.idempotence=true) AND transactional producers + consumers. Kafka ensures each message is written exactly once even with retries. Combined with Flink's two-phase commit, this gives exactly-once end-to-end. Performance overhead: ~20% throughput reduction.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What happens to in-flight Flink state when a node crashes?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Flink recovers from its last checkpoint.</strong><br><br>Every 60 seconds (configurable), Flink performs a distributed snapshot: all operator states (Count-Min Sketch, local heap, Bloom filter) are saved to S3. The corresponding Kafka offset consumed up to that point is also saved.<br><br>On crash: Flink restarts from the last successful checkpoint. It resumes reading Kafka from the saved offset. Events between the checkpoint and the crash are replayed from Kafka (this is why Kafka retention matters). State is restored from S3.<br><br>If Flink uses exactly-once mode (two-phase commit), the output (writes to Redis/Cassandra) is also rolled back if the checkpoint was not completed. This prevents double-counting even across crashes.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you handle late-arriving events in Flink?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Watermarks and allowed lateness.</strong><br><br><strong>The problem:</strong> Events arrive out of order. An event with timestamp t=14:23:45 might arrive at t=14:24:10 (25 seconds late) due to network delays. If the 30-second window for 14:23 already closed and was flushed, what do you do?<br><br><strong>Watermarks:</strong> Flink maintains a \"watermark\" \u2014 its best guess of the current event time. A watermark of t=14:24:00 means \"all events with timestamp &lt; 14:24:00 have probably arrived.\" Windows only close when the watermark passes the window end time.<br><br><strong>Allowed lateness:</strong> Even after a window closes, Flink can wait for late events up to X seconds. Late events trigger a window update (re-emit corrected results). Events arriving after the allowed lateness are either dropped or sent to a side output for separate handling.<br><br>In Top-K, we use a 5-second watermark lag \u2014 accepting that our Top-K results may be 5 seconds stale in exchange for near-complete accuracy.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Why does Kafka partitioning by entity_id matter so much for Top-K?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>It eliminates cross-worker coordination \u2014 the fundamental scalability trick.</strong><br><br>If all events for video_123 go to the same Kafka partition, they're consumed by the same Flink worker. That worker maintains the local count for video_123 in its own Count-Min Sketch, entirely in local memory. No network calls needed to coordinate with other workers.<br><br>If video_123's events were spread across multiple partitions, three things would go wrong: (1) Multiple Flink workers would each have a partial count for video_123. (2) To merge them, every worker would need to communicate with every other worker after each event. (3) At 500K events/sec, this coordination traffic would overwhelm the cluster.<br><br>Partitioning by entity_id makes the problem embarrassingly parallel \u2014 each worker handles a disjoint subset of entities, does all its computation locally, and the only cross-worker step is the final merge of top-K lists at flush time.</div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">Can you replace Kafka with a database in the streaming pipeline?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\"><strong>Technically yes, practically no \u2014 and interviewers will probe this.</strong><br><br>You could write events to a PostgreSQL table and have Flink poll it. This is called \"Change Data Capture\" (CDC) and it works for low-throughput pipelines. But it fails at 500K events/sec because:<br><br>1. Each INSERT is a full row write with WAL logging \u2014 massive I/O overhead at scale.<br>2. Polling introduces latency: Flink polls every X seconds, creating inherent lag.<br>3. Ordering guarantees are weak: multiple writers can write with slightly different timestamps.<br>4. Backpressure handling: if Flink falls behind, the database table grows unbounded (no TTL like Kafka retention).<br>5. Multiple consumers: each consumer needs its own polling mechanism and state tracking.<br><br>Kafka is purpose-built for this. Its log-structured storage makes sequential writes extremely fast. Consumers maintain their own offset. Backpressure is handled naturally \u2014 consumers just read slower while Kafka buffers the data within retention limits.</div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">STREAMING \u00b7 KAFKA \u00b7 FLINK \u00b7 KINESIS \u00b7 SPARK \u00b7 MANISH-ALMANAC</div>\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Streaming' },
  protocols:   { title: 'API Protocols Decoded',           srcdoc: "<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n<meta charset=\"UTF-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n<title>API Protocols: REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling</title>\n<link href=\"https://fonts.googleapis.com/css2?family=Playfair+Display:wght@700;900&family=Source+Sans+3:wght@300;400;500;600&family=JetBrains+Mono:wght@400;600&display=swap\" rel=\"stylesheet\">\n<style>\n:root{\n  --ink:#0f0e0c;--page:#f7f5f0;--surface:#eeecea;--surface2:#e5e2dc;--border:#d4d0c8;--muted:#7a7568;\n  --rest:#1a4f8a;--rest-bg:#edf2fb;\n  --grpc:#1a7a4a;--grpc-bg:#edf8f2;\n  --gql:#a0208a;--gql-bg:#faedf8;\n  --ws:#b8720a;--ws-bg:#fdf6e8;\n  --sse:#1287b1;--sse-bg:#eaf6fb;\n  --lp:#6040a0;--lp-bg:#f2eefb;\n  --red:#c0392b;--red-bg:#fdf0ee;\n  --green:#1a7a4a;--green-bg:#edf8f2;\n  --amber:#b8720a;--amber-bg:#fdf6e8;\n  --blue:#1a4f8a;--blue-bg:#edf2fb;\n  --mono:'JetBrains Mono',monospace;--serif:'Playfair Display',serif;--sans:'Source Sans 3',sans-serif;\n}\n*{box-sizing:border-box;margin:0;padding:0;}html{scroll-behavior:smooth;}\nbody{background:var(--page);color:var(--ink);font-family:var(--sans);font-size:15px;line-height:1.75;}\n.hero{background:var(--ink);color:#e8e4dc;padding:72px 24px 56px;position:relative;overflow:hidden;}\n.hero::before{content:'';position:absolute;inset:0;background:repeating-linear-gradient(45deg,transparent,transparent 40px,rgba(255,255,255,.015) 40px,rgba(255,255,255,.015) 41px);}\n.hero-inner{max-width:960px;margin:0 auto;position:relative;}\n.hero-tag{font-family:var(--mono);font-size:10px;letter-spacing:4px;color:#6a6458;text-transform:uppercase;margin-bottom:20px;}\nh1{font-family:var(--serif);font-size:clamp(32px,5vw,58px);font-weight:900;line-height:1.05;letter-spacing:-.5px;margin-bottom:20px;color:#f0ece4;}\nh1 em{color:#e8b84b;font-style:normal;}\n.hero-sub{font-size:15px;color:#7a7060;max-width:640px;line-height:1.7;margin-bottom:32px;}\n.db-pills{display:flex;flex-wrap:wrap;gap:8px;}\n.db-pill{font-family:var(--mono);font-size:10px;padding:5px 14px;border-radius:3px;border:1px solid;letter-spacing:.5px;}\n.pill-rest{border-color:var(--rest);color:var(--rest);background:rgba(26,79,138,.08);}\n.pill-grpc{border-color:var(--grpc);color:var(--grpc);background:rgba(26,122,74,.08);}\n.pill-gql{border-color:var(--gql);color:var(--gql);background:rgba(160,32,138,.08);}\n.pill-ws{border-color:var(--ws);color:var(--ws);background:rgba(184,114,10,.08);}\n.pill-sse{border-color:var(--sse);color:var(--sse);background:rgba(18,135,177,.08);}\n.pill-lp{border-color:var(--lp);color:var(--lp);background:rgba(96,64,160,.08);}\n.nav{position:sticky;top:0;z-index:100;background:var(--ink);border-bottom:1px solid #1e1c18;display:flex;overflow-x:auto;scrollbar-width:none;padding:0 20px;}\n.nav::-webkit-scrollbar{display:none;}\n.nav a{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:#4a4840;text-decoration:none;padding:14px 12px;white-space:nowrap;border-bottom:2px solid transparent;transition:.18s;}\n.nav a:hover{color:#e8b84b;border-color:#e8b84b;}\n.wrap{max-width:960px;margin:0 auto;padding:0 20px;}\nsection{padding:56px 0 36px;border-bottom:2px solid var(--border);}\nsection:last-child{border:none;}\n.sec-tag{font-family:var(--mono);font-size:9px;letter-spacing:4px;text-transform:uppercase;color:var(--muted);margin-bottom:8px;display:flex;align-items:center;gap:10px;}\n.sec-tag::before{content:'';width:20px;height:1px;background:var(--border);}\nh2{font-family:var(--serif);font-size:clamp(22px,3.5vw,32px);font-weight:700;line-height:1.15;margin-bottom:18px;}\nh3{font-family:var(--sans);font-size:17px;font-weight:600;margin:32px 0 10px;border-bottom:1px solid var(--border);padding-bottom:6px;}\nh4{font-size:13px;font-weight:600;margin:16px 0 6px;text-transform:uppercase;letter-spacing:.5px;}\np{color:#3a3830;font-size:14.5px;margin-bottom:12px;max-width:820px;}\nstrong{color:var(--ink);}\ncode{font-family:var(--mono);font-size:11.5px;background:var(--surface2);padding:1px 5px;border-radius:3px;color:var(--blue);}\n/* Protocol identity cards */\n.db-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(200px,1fr));gap:14px;margin:24px 0;}\n.db-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;overflow:hidden;}\n.db-card::before{content:'';position:absolute;top:0;left:0;right:0;height:4px;}\n.db-card.rest::before{background:var(--rest);}\n.db-card.grpc::before{background:var(--grpc);}\n.db-card.gql::before{background:var(--gql);}\n.db-card.ws::before{background:var(--ws);}\n.db-card.sse::before{background:var(--sse);}\n.db-card.lp::before{background:var(--lp);}\n.db-logo{font-size:22px;margin-bottom:6px;}\n.db-name{font-family:var(--serif);font-size:17px;font-weight:700;margin-bottom:4px;}\n.db-type{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:var(--muted);margin-bottom:10px;text-transform:uppercase;}\n.db-tagline{font-size:13px;color:#5a5848;line-height:1.55;}\n.db-born{font-family:var(--mono);font-size:9px;color:var(--muted);margin-top:8px;}\n/* Analogy block */\n.analogy{background:var(--ink);color:#c8c4b8;border-radius:8px;padding:24px 28px;margin:24px 0;}\n.analogy-label{font-family:var(--mono);font-size:9px;letter-spacing:3px;color:#6a6458;margin-bottom:10px;text-transform:uppercase;}\n.analogy-text{font-size:15px;line-height:1.75;color:#d8d4c8;}\n.analogy-text strong{color:#e8b84b;}\n/* Callouts */\n.callout{border-radius:4px;padding:14px 18px;margin:18px 0;font-size:13.5px;border-left:3px solid;line-height:1.65;}\n.callout p{font-size:13.5px;margin-bottom:6px;}.callout p:last-child{margin:0;}\n.cl-blue{background:var(--blue-bg);border-color:var(--blue);color:#1a2a4a;}\n.cl-green{background:var(--green-bg);border-color:var(--green);color:#0a2a1a;}\n.cl-amber{background:var(--amber-bg);border-color:var(--amber);color:#3a2a08;}\n.cl-red{background:var(--red-bg);border-color:var(--red);color:#3a0a08;}\n.cl-lbl{font-family:var(--mono);font-size:9px;letter-spacing:3px;text-transform:uppercase;margin-bottom:6px;opacity:.7;}\n/* Comparison table */\n.comp-table{width:100%;border-collapse:collapse;margin:20px 0;font-size:13px;}\n.comp-table th{padding:10px 14px;border:1px solid var(--border);background:var(--surface2);font-family:var(--mono);font-size:9px;letter-spacing:1.5px;text-transform:uppercase;color:var(--muted);}\n.comp-table td{padding:11px 14px;border:1px solid var(--border);vertical-align:top;color:#3a3830;line-height:1.6;}\n.comp-table .row-head{font-family:var(--mono);font-size:11px;font-weight:600;background:var(--surface);color:var(--ink);white-space:nowrap;}\n.good{color:var(--green);font-weight:600;}.warn{color:var(--amber);font-weight:600;}.bad{color:var(--red);font-weight:600;}\n/* System design examples */\n.sd-example{background:white;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.sd-example-head{background:var(--ink);padding:14px 20px;display:flex;align-items:center;gap:12px;}\n.sd-example-title{font-family:var(--serif);font-size:16px;color:#f0ece4;font-weight:700;}\n.sd-example-tag{font-family:var(--mono);font-size:9px;letter-spacing:2px;color:#6a6458;border:1px solid #2e2c28;padding:3px 8px;border-radius:2px;}\n.sd-example-body{padding:20px;}\n.choice-row{display:flex;gap:10px;align-items:flex-start;padding:10px 0;border-bottom:1px solid var(--border);font-size:13px;}\n.choice-row:last-child{border:none;}\n.choice-label{font-family:var(--mono);font-size:10px;letter-spacing:1px;color:var(--muted);width:130px;flex-shrink:0;padding-top:2px;}\n.choice-val{flex:1;color:#3a3830;line-height:1.6;}\n/* Badges */\n.badge{display:inline-block;font-family:var(--mono);font-size:9px;padding:2px 7px;border-radius:2px;border:1px solid;margin-right:4px;font-weight:500;}\n.b-rest{background:var(--rest-bg);border-color:var(--rest);color:var(--rest);}\n.b-grpc{background:var(--grpc-bg);border-color:var(--grpc);color:var(--grpc);}\n.b-gql{background:var(--gql-bg);border-color:var(--gql);color:var(--gql);}\n.b-ws{background:var(--ws-bg);border-color:var(--ws);color:var(--ws);}\n.b-sse{background:var(--sse-bg);border-color:var(--sse);color:var(--sse);}\n.b-lp{background:var(--lp-bg);border-color:var(--lp);color:var(--lp);}\n.b-g{background:var(--green-bg);border-color:var(--green);color:var(--green);}\n.b-r{background:var(--red-bg);border-color:var(--red);color:var(--red);}\n.b-a{background:var(--amber-bg);border-color:var(--amber);color:var(--amber);}\n/* FAQ */\n.faq-item{border:1px solid var(--border);border-radius:4px;margin-bottom:8px;overflow:hidden;}\n.faq-q{padding:14px 18px;display:flex;justify-content:space-between;align-items:center;cursor:pointer;background:white;font-size:14px;font-weight:500;color:var(--ink);user-select:none;}\n.faq-q:hover{background:var(--surface);}\n.faq-q .tog{font-size:18px;color:#e8b84b;flex-shrink:0;margin-left:12px;transition:transform .2s;font-family:var(--mono);}\n.faq-a{display:none;padding:18px;background:var(--surface);font-size:13.5px;color:#3a3830;line-height:1.75;border-top:1px solid var(--border);}\n.faq-item.open .faq-a{display:block;}.faq-item.open .tog{transform:rotate(45deg);}\n.faq-a ul{padding-left:18px;margin:8px 0;}.faq-a li{margin-bottom:6px;}\n/* Concept grid */\n.concept-grid{display:grid;grid-template-columns:1fr;gap:0;margin:20px 0;border:1px solid var(--border);border-radius:8px;overflow:hidden;}\n.concept-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.concept-row:last-child{border-bottom:none;}\n.concept-term{background:var(--ink);color:#e8b84b;font-family:var(--mono);font-size:11.5px;font-weight:600;min-width:155px;padding:14px 16px;flex-shrink:0;border-right:1px solid #2a2820;display:flex;align-items:flex-start;line-height:1.5;}\n.concept-def{padding:13px 16px;flex:1;font-size:13.5px;color:#3a3830;line-height:1.7;background:#fff;}\n.concept-def strong{color:var(--ink);}\n.concept-def code{background:var(--surface);padding:1px 5px;border-radius:3px;font-family:var(--mono);font-size:11px;color:var(--blue);}\n/* Step block */\n.step-block{background:#fff;border:1px solid var(--border);border-radius:8px;margin:20px 0;overflow:hidden;}\n.step-block-header{background:var(--ink);color:#e8e4dc;padding:13px 18px;font-family:var(--mono);font-size:10px;letter-spacing:2px;text-transform:uppercase;display:flex;align-items:center;gap:10px;}\n.sb-icon{font-size:16px;}\n.step-block-body{padding:0;}\n.step-row{display:flex;gap:0;border-bottom:1px solid var(--border);}\n.step-row:last-child{border-bottom:none;}\n.step-num{background:var(--surface);min-width:46px;display:flex;align-items:flex-start;justify-content:center;padding:16px 6px;font-family:var(--mono);font-size:11px;font-weight:700;color:var(--muted);flex-shrink:0;border-right:1px solid var(--border);}\n.step-content{padding:14px 18px;flex:1;}\n.step-q{font-weight:600;font-size:14px;color:var(--ink);margin-bottom:10px;}\n.step-options{display:flex;flex-direction:column;gap:6px;}\n.step-option{display:flex;gap:10px;align-items:flex-start;padding:9px 13px;border-radius:5px;font-size:13px;line-height:1.65;}\n.opt-yes{background:#edf8f2;border:1px solid #b8ddc8;}\n.opt-no{background:#fdf6e8;border:1px solid #e8c870;}\n.opt-mid{background:#edf2fb;border:1px solid #b8c8e8;}\n.opt-any{background:#f4f0fb;border:1px solid #c8b8e8;}\n.opt-arrow{font-family:var(--mono);font-size:12px;font-weight:700;flex-shrink:0;margin-top:1px;min-width:130px;}\n.opt-yes .opt-arrow{color:#1a7a4a;}\n.opt-no .opt-arrow{color:#b8720a;}\n.opt-mid .opt-arrow{color:#1a4f8a;}\n.opt-any .opt-arrow{color:#5a3c9a;}\n.opt-text{flex:1;color:#3a3830;}\n/* Use-card grid */\n.use-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:14px;margin:20px 0;}\n.use-card{border:1px solid var(--border);border-radius:6px;padding:18px;background:white;}\n.use-card-head{font-family:var(--mono);font-size:11px;font-weight:600;margin-bottom:10px;display:flex;align-items:center;gap:8px;}\n.use-card ul{padding-left:16px;font-size:13px;color:#4a4838;line-height:1.7;}\n.use-card ul li{margin-bottom:4px;}\n/* Combo pattern cards */\n.combo-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(280px,1fr));gap:16px;margin:20px 0;}\n.combo-card{background:white;border:1px solid var(--border);border-radius:8px;padding:20px;position:relative;}\n.combo-card::before{content:'';position:absolute;top:0;left:0;right:0;height:3px;border-radius:8px 8px 0 0;}\n.combo-card.c1::before{background:linear-gradient(90deg,var(--rest),var(--ws));}\n.combo-card.c2::before{background:linear-gradient(90deg,var(--rest),var(--sse));}\n.combo-card.c3::before{background:linear-gradient(90deg,var(--grpc),var(--grpc));}\n.combo-card.c4::before{background:linear-gradient(90deg,var(--gql),var(--ws));}\n.combo-card.c5::before{background:linear-gradient(90deg,var(--rest),var(--lp));}\n.combo-card.c6::before{background:linear-gradient(90deg,var(--rest),var(--grpc));}\n.combo-title{font-family:var(--serif);font-size:15px;font-weight:700;margin-bottom:6px;color:var(--ink);}\n.combo-formula{font-family:var(--mono);font-size:11px;color:var(--muted);margin-bottom:12px;letter-spacing:.5px;}\n.combo-body{font-size:13px;color:#5a5848;line-height:1.65;margin-bottom:10px;}\n.combo-used{font-family:var(--mono);font-size:10px;color:var(--muted);}\n/* Footer */\n.footer{background:var(--ink);text-align:center;padding:36px 20px;font-family:var(--mono);font-size:10px;color:#3a3830;letter-spacing:2px;}\n/* Responsive */\n@media(max-width:560px){\n  .concept-row{flex-direction:column;}.concept-term{min-width:auto;border-right:none;border-bottom:1px solid #2a2820;}\n  .opt-arrow{min-width:80px;}.choice-label{width:80px;}\n}\n</style>\n</head>\n<body>\n\n<div class=\"hero\">\n  <div class=\"hero-inner\">\n    <div class=\"hero-tag\">System Design \u00b7 API Design \u00b7 Manish-Almanac</div>\n    <h1>API Protocols<br><em>Decoded</em></h1>\n    <p class=\"hero-sub\">REST vs gRPC vs GraphQL vs WebSocket vs SSE vs Long Polling \u2014 every dimension that matters in a FAANG interview, explained from first principles. Includes when they complement each other, real system design examples, and every follow-up answered.</p>\n    <div class=\"db-pills\">\n      <span class=\"db-pill pill-rest\">REST</span>\n      <span class=\"db-pill pill-grpc\">gRPC</span>\n      <span class=\"db-pill pill-gql\">GraphQL</span>\n      <span class=\"db-pill pill-ws\">WebSocket</span>\n      <span class=\"db-pill pill-sse\">SSE</span>\n      <span class=\"db-pill pill-lp\">Long Polling</span>\n    </div>\n  </div>\n</div>\n\n<nav class=\"nav\">\n  <a href=\"#mental-model\">Mental Model</a>\n  <a href=\"#request-response\">Request-Response</a>\n  <a href=\"#realtime\">Real-Time</a>\n  <a href=\"#comparison\">Full Comparison</a>\n  <a href=\"#combos\">Combos</a>\n  <a href=\"#examples\">System Design</a>\n  <a href=\"#decision\">Decision Tree</a>\n  <a href=\"#followups\">Follow-ups</a>\n</nav>\n\n<div class=\"wrap\">\n\n<!-- \u2550\u2550 00 MENTAL MODEL \u2550\u2550 -->\n<section id=\"mental-model\">\n  <div class=\"sec-tag\">00 \u00b7 Start Here</div>\n  <h2>The mental model before memorising anything</h2>\n\n  <p>Most candidates treat REST, WebSocket, gRPC, and GraphQL as competing options. They're not \u2014 they solve <strong>different communication problems</strong>. Before picking any protocol, answer one question:</p>\n\n  <div class=\"callout cl-amber\">\n    <div class=\"cl-lbl\">The single question that matters</div>\n    <p><strong>Who initiates communication, and how often does data change?</strong></p>\n    <p>Client asks once, server replies once \u2192 <strong>Request-Response</strong> (REST, gRPC, GraphQL)</p>\n    <p>Server needs to push data to client without the client asking \u2192 <strong>Server Push</strong> (SSE, WebSocket, Long Polling)</p>\n    <p>Client and server need to talk simultaneously, continuously \u2192 <strong>Bidirectional</strong> (WebSocket, gRPC streaming)</p>\n  </div>\n\n  <div class=\"analogy\">\n    <div class=\"analogy-label\">The restaurant analogy \u2014 for a complete layman</div>\n    <div class=\"analogy-text\">\n      <strong>REST</strong> is a waiter who takes your order, goes to the kitchen, and comes back with exactly what you asked for. Simple, stateless, everyone knows the rules.<br><br>\n      <strong>gRPC</strong> is a waiter using a walkie-talkie with the kitchen using a shared codebook. Faster, more efficient, but both sides need the same codebook (Protobuf schema).<br><br>\n      <strong>GraphQL</strong> is a waiter who lets you design your own plate. \"I want 3 items from dish A and 2 from dish B, in one trip.\" You get exactly what you asked for \u2014 nothing more, nothing less.<br><br>\n      <strong>WebSocket</strong> is a phone call \u2014 once connected, both sides can speak at any moment without hanging up and redialling.<br><br>\n      <strong>SSE</strong> is a radio broadcast \u2014 the server talks continuously to all listeners, but listeners can't transmit back on the same channel.<br><br>\n      <strong>Long Polling</strong> is repeatedly calling the kitchen and asking \"is my order ready yet?\" \u2014 the kitchen keeps you on hold until it is, then hangs up. You immediately call back.\n    </div>\n  </div>\n\n  <h3>The Two Families</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Request-Response</div>\n      <div class=\"concept-def\"><strong>Client sends a request, server replies, connection closes.</strong> Each interaction is independent. The server has no memory of previous requests unless you send a session token.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: REST, gRPC (unary), GraphQL Query/Mutation. HTTP/1.1, HTTP/2, HTTP/3 are the transports.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Persistent / Push</div>\n      <div class=\"concept-def\"><strong>Connection stays open. Server can push data without the client asking.</strong> Crucial for real-time features: live feeds, notifications, chat, collaborative editing.<br><span style=\"color:#5a5848;font-size:12.5px;\">Members: WebSocket (bidirectional), SSE (server\u2192client only), Long Polling (simulated push), gRPC streaming.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 01 REQUEST-RESPONSE PROTOCOLS \u2550\u2550 -->\n<section id=\"request-response\">\n  <div class=\"sec-tag\">01 \u00b7 Request-Response Family</div>\n  <h2>REST, gRPC, and GraphQL \u2014 the three ways to ask</h2>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card rest\">\n      <div class=\"db-logo\">\ud83c\udf10</div>\n      <div class=\"db-name\">REST</div>\n      <div class=\"db-type\">HTTP \u00b7 Stateless \u00b7 Resource-Oriented</div>\n      <div class=\"db-tagline\">The universal default. Every HTTP client speaks it. Resources are nouns (URLs), actions are verbs (GET/POST/PUT/DELETE). No special tooling needed. The right choice until it isn't.</div>\n      <div class=\"db-born\">Born 2000 \u00b7 Roy Fielding's PhD thesis \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card grpc\">\n      <div class=\"db-logo\">\u26a1</div>\n      <div class=\"db-name\">gRPC</div>\n      <div class=\"db-type\">HTTP/2 \u00b7 Binary \u00b7 Contract-First</div>\n      <div class=\"db-tagline\">Google's internal RPC framework. Define your API in a .proto file \u2014 both sides generate code from it. Binary encoding (Protobuf) makes it 5\u201310x smaller and faster than JSON REST. Built for internal service-to-service calls.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Google \u00b7 HTTP/2 + Protobuf</div>\n    </div>\n    <div class=\"db-card gql\">\n      <div class=\"db-logo\">\u25c8</div>\n      <div class=\"db-name\">GraphQL</div>\n      <div class=\"db-type\">HTTP \u00b7 Query Language \u00b7 Client-Driven</div>\n      <div class=\"db-tagline\">Facebook's answer to REST's over-fetching problem. The client describes exactly what data it needs in a typed query. One endpoint, infinite flexibility. Ideal when different clients (mobile/web/partner) need different shapes of the same data.</div>\n      <div class=\"db-born\">Born 2015 \u00b7 Facebook \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n  </div>\n\n  <h3>REST \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Resources & Verbs</div>\n      <div class=\"concept-def\"><strong>REST maps actions to HTTP methods and nouns to URLs.</strong><br>\n        <code>GET /users/123</code> \u2192 fetch user<br>\n        <code>POST /users</code> \u2192 create user<br>\n        <code>PUT /users/123</code> \u2192 replace user<br>\n        <code>PATCH /users/123</code> \u2192 partial update<br>\n        <code>DELETE /users/123</code> \u2192 delete user<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">The URL is the resource (noun). The HTTP method is the action (verb). This separation is REST's core design principle.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Stateless</div>\n      <div class=\"concept-def\"><strong>Every request must contain everything the server needs to process it.</strong> The server stores no session between requests. Identity always comes from a token in the header \u2014 never assumed from context.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Statelessness makes REST trivially horizontally scalable \u2014 any server can handle any request. No sticky sessions needed.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP Caching</div>\n      <div class=\"concept-def\"><strong>GET requests are cacheable by default</strong> \u2014 CDNs, browsers, and proxies can cache them. This is one of REST's biggest advantages over gRPC and GraphQL.<br><code>Cache-Control: max-age=3600</code> tells every layer to cache for 1 hour.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A public REST API with GET responses cached at Cloudflare reduces origin traffic by 95%+. gRPC and GraphQL cannot use HTTP caching natively.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Status Codes</div>\n      <div class=\"concept-def\"><strong>HTTP status codes carry semantic meaning every client understands natively:</strong><br>\n        <code>200</code> OK \u00b7 <code>201</code> Created \u00b7 <code>204</code> No Content<br>\n        <code>400</code> Bad Request \u00b7 <code>401</code> Unauthorised \u00b7 <code>403</code> Forbidden \u00b7 <code>404</code> Not Found<br>\n        <code>429</code> Rate Limited \u00b7 <code>500</code> Server Error \u00b7 <code>503</code> Unavailable<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Every HTTP client, load balancer, and monitoring tool understands these codes. GraphQL always returns 200 \u2014 errors are in the response body, invisible to infrastructure.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Over-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's biggest weakness: you get what the endpoint returns, not what you need.</strong><br><code>GET /users/123</code> returns all 40 fields. Your mobile app only needed name and avatar.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile with limited bandwidth, over-fetching wastes data and slows rendering. This is exactly why Facebook invented GraphQL.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Under-Fetching</div>\n      <div class=\"concept-def\"><strong>REST's second weakness: one endpoint rarely returns all the data you need.</strong><br>To show a user's profile with their posts and followers: <code>GET /users/123</code> + <code>GET /users/123/posts</code> + <code>GET /users/123/followers</code> \u2014 3 round trips.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f On mobile, each extra round trip adds 50\u2013200ms. Waterfall requests add up fast. GraphQL solves this with a single query.</span></div>\n    </div>\n  </div>\n\n  <h3>gRPC \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Protocol Buffers</div>\n      <div class=\"concept-def\"><strong>gRPC uses Protobuf \u2014 a binary serialisation format \u2014 instead of JSON.</strong> You define your data schema in a <code>.proto</code> file. Both client and server generate code from it automatically.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Binary is 5\u201310x smaller than equivalent JSON. Parsing binary is 5\u201310x faster than parsing JSON text. At 1M requests/sec, this matters enormously.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>gRPC runs on HTTP/2, which multiplexes multiple requests over a single TCP connection.</strong> With HTTP/1.1 REST, each request needs its own connection (or connection pooling). HTTP/2 sends hundreds of requests simultaneously over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Huge advantage for service-to-service calls where you're making thousands of RPCs per second between the same two services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Streaming Modes</div>\n      <div class=\"concept-def\"><strong>gRPC supports 4 modes \u2014 REST only supports request-response:</strong><br>\n        <strong>Unary</strong> \u2014 one request, one response (like REST)<br>\n        <strong>Server streaming</strong> \u2014 one request, stream of responses (like SSE)<br>\n        <strong>Client streaming</strong> \u2014 stream of requests, one response (uploading chunks)<br>\n        <strong>Bidirectional streaming</strong> \u2014 both sides stream simultaneously (like WebSocket)<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Real example: Google Maps sends your location as a client stream, receives route updates as a server stream \u2014 all over one gRPC bidirectional connection.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Schema Contract</div>\n      <div class=\"concept-def\"><strong>The .proto file is a strict API contract between client and server.</strong> Both sides must use the same schema. Adding a field is backwards-compatible; removing one breaks older clients.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f gRPC requires code generation on every schema change. REST and GraphQL don't. This is operational overhead \u2014 significant for teams with many services.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Browser Support</div>\n      <div class=\"concept-def\"><strong>Browsers cannot call gRPC directly.</strong> HTTP/2 trailers (which gRPC uses) are not exposed by browser APIs. You need gRPC-Web (a proxy layer) or gRPC-Gateway (which translates to REST).<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f This is why gRPC is almost exclusively used for internal service-to-service communication, not for public-facing APIs.</span></div>\n    </div>\n  </div>\n\n  <h3>GraphQL \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Single Endpoint</div>\n      <div class=\"concept-def\"><strong>GraphQL has one endpoint: <code>POST /graphql</code>.</strong> The query in the request body describes exactly what data to return. No URL routing, no versioning headaches \u2014 the schema evolves by adding fields (never removing).<br><span style=\"color:#5a5848;font-size:12.5px;\">This is how Facebook, GitHub, Shopify, and Twitter serve data to their apps \u2014 one endpoint, infinite flexibility.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Query vs Mutation</div>\n      <div class=\"concept-def\"><strong>Query</strong> = read (like GET). <strong>Mutation</strong> = write (like POST/PUT/DELETE). <strong>Subscription</strong> = real-time push (like WebSocket).<br>\n        <code>query { user(id:\"123\") { name, avatar, followerCount } }</code><br>\n        <code>mutation { createPost(input:{...}) { id, createdAt } }</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Subscriptions use WebSocket under the hood \u2014 GraphQL is a query language on top of a transport, not a transport itself.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">N+1 Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL's biggest pitfall: a single query can trigger hundreds of database calls.</strong><br>Query for 100 posts, each needing its author \u2192 1 query for posts + 100 queries for authors = 101 DB calls.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Fix: DataLoader (batches and deduplicates database calls). Every GraphQL implementation needs it or performance degrades to unusable.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Introspection</div>\n      <div class=\"concept-def\"><strong>GraphQL APIs are self-documenting.</strong> Clients can query the schema itself to discover all available types, fields, and operations \u2014 no separate Swagger/OpenAPI needed.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Tools like GraphiQL and Apollo Studio give developers interactive playgrounds. New team members explore the API without reading docs.</span><br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Disable introspection in production \u2014 it exposes your entire data model to attackers.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Caching Problem</div>\n      <div class=\"concept-def\"><strong>GraphQL uses POST for queries \u2014 HTTP caching doesn't work natively.</strong> CDNs only cache GET requests. Every GraphQL query hits your origin.<br><span style=\"color:#5a5848;font-size:12.5px;\">Workarounds: Persisted Queries (assign each query a hash, send hash as GET), Apollo CDN caching, or Cloudflare Workers. More complexity than REST's built-in GET caching.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 02 REAL-TIME PROTOCOLS \u2550\u2550 -->\n<section id=\"realtime\">\n  <div class=\"sec-tag\">02 \u00b7 Real-Time Family</div>\n  <h2>WebSocket, SSE, and Long Polling \u2014 the three ways to push</h2>\n\n  <div class=\"callout cl-blue\">\n    <div class=\"cl-lbl\">Why REST can't do real-time</div>\n    <p>REST is pull-only: <strong>the client must ask</strong> before the server can respond. For a chat app, polling every second means thousands of empty responses. For a live dashboard, you'd poll 60 times/minute per user. At 100K users, that's 6M requests/minute for mostly empty data.</p>\n    <p><strong>Real-time protocols invert this: the server pushes data the moment it's available.</strong> No polling, no wasted requests, no latency from the polling interval.</p>\n  </div>\n\n  <div class=\"db-grid\">\n    <div class=\"db-card ws\">\n      <div class=\"db-logo\">\ud83d\udd0c</div>\n      <div class=\"db-name\">WebSocket</div>\n      <div class=\"db-type\">Full-Duplex \u00b7 Persistent \u00b7 TCP</div>\n      <div class=\"db-tagline\">A persistent bidirectional connection over a single TCP socket. Once the HTTP handshake upgrades to WS, both client and server can send messages at any time, simultaneously. The gold standard for true real-time: chat, multiplayer games, collaborative editing.</div>\n      <div class=\"db-born\">Born 2011 \u00b7 RFC 6455 \u00b7 HTTP Upgrade handshake</div>\n    </div>\n    <div class=\"db-card sse\">\n      <div class=\"db-logo\">\ud83d\udce1</div>\n      <div class=\"db-name\">Server-Sent Events</div>\n      <div class=\"db-type\">Server\u2192Client Only \u00b7 HTTP \u00b7 Auto-Reconnect</div>\n      <div class=\"db-tagline\">A simple HTTP connection that stays open. The server pushes text events whenever it wants. The client cannot send data back on this connection. Simpler than WebSocket, works with HTTP/2 multiplexing, and auto-reconnects on disconnect.</div>\n      <div class=\"db-born\">Born 2006 \u00b7 W3C Standard \u00b7 HTTP/1.1 + HTTP/2</div>\n    </div>\n    <div class=\"db-card lp\">\n      <div class=\"db-logo\">\ud83d\udd04</div>\n      <div class=\"db-name\">Long Polling</div>\n      <div class=\"db-type\">Simulated Push \u00b7 HTTP \u00b7 Request-Response</div>\n      <div class=\"db-tagline\">Client sends a request. Server holds it open until data is available or a timeout occurs. Client immediately sends a new request. Simulates real-time over plain HTTP \u2014 no special protocol needed. The legacy fallback when WebSocket isn't available.</div>\n      <div class=\"db-born\">Born ~2000s \u00b7 No official standard \u00b7 Plain HTTP</div>\n    </div>\n  </div>\n\n  <h3>WebSocket \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Upgrade Handshake</div>\n      <div class=\"concept-def\"><strong>WebSocket starts as an HTTP request, then upgrades to a persistent TCP connection.</strong><br>\n        Client sends: <code>GET /ws HTTP/1.1, Upgrade: websocket</code><br>\n        Server responds: <code>101 Switching Protocols</code><br>\n        Now: raw TCP frames flow in both directions \u2014 no HTTP overhead per message.<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Why HTTP start? Firewalls and proxies block arbitrary TCP but allow HTTP port 80/443. The upgrade trick bypasses firewall restrictions.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Full-Duplex</div>\n      <div class=\"concept-def\"><strong>Both client and server can send messages at any moment, simultaneously, over the same connection.</strong> No waiting for the other side. No request-response cycle.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This is why WebSocket is used for chat (user sends and receives simultaneously), multiplayer games (constant position updates both directions), and collaborative editing (every keystroke sent immediately).</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Framing</div>\n      <div class=\"concept-def\"><strong>WebSocket sends data as frames, not HTTP requests.</strong> Each frame has a tiny 2\u201310 byte header (opcode, mask, length) vs HTTP's 200\u2013800 byte headers per request.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 A chat message sent via WebSocket costs ~10 bytes overhead. Via HTTP polling: 300\u2013800 bytes of headers per poll even when empty. At 1M active users, this difference is measured in gigabits per second.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">State & Scaling</div>\n      <div class=\"concept-def\"><strong>WebSocket connections are stateful and sticky \u2014 the connection lives on a specific server.</strong> If that server dies, all its connections drop. Clients must reconnect.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f You cannot load-balance WebSocket with standard round-robin. You need sticky sessions (by user_id) or a pub/sub broker (Redis, Kafka) so any server can push to any user regardless of which server they're connected to.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Heartbeats</div>\n      <div class=\"concept-def\"><strong>Idle WebSocket connections get killed by proxies and NAT gateways after 30\u201390 seconds.</strong> Solution: ping/pong heartbeat every 20\u201330 seconds. Server sends a ping frame, client echoes a pong. No pong = connection dead, clean up and notify.<br><span style=\"color:#5a5848;font-size:12.5px;\">Every production WebSocket implementation needs heartbeat logic. Without it, you get ghost connections \u2014 the server thinks the client is connected but the client is gone.</span></div>\n    </div>\n  </div>\n\n  <h3>SSE \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Wire Format</div>\n      <div class=\"concept-def\"><strong>SSE is a plain HTTP response that never ends.</strong> Content-Type is <code>text/event-stream</code>. The server sends newline-delimited text events:<br>\n        <code>data: {\"type\":\"view\",\"count\":1247}\\n\\n</code><br>\n        <code>data: {\"type\":\"view\",\"count\":1248}\\n\\n</code><br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Two consecutive newlines signal the end of one event. The browser's EventSource API parses this automatically and fires events at your JavaScript handler.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Auto-Reconnect</div>\n      <div class=\"concept-def\"><strong>The browser's EventSource automatically reconnects after a disconnect.</strong> The server sends an event ID with each event. On reconnect, the browser sends <code>Last-Event-ID</code> header \u2014 the server can replay missed events.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 This makes SSE dramatically simpler to operate than WebSocket. No custom reconnect logic needed on the client. Works out of the box.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">HTTP/2 Multiplexing</div>\n      <div class=\"concept-def\"><strong>Over HTTP/2, multiple SSE streams share one TCP connection.</strong> With HTTP/1.1, browsers limit connections per domain (typically 6). If you have 6 SSE streams, you've used all connections. HTTP/2 multiplexes hundreds over one connection.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Use HTTP/2 for SSE at scale. HTTP/1.1 SSE has a hard limit of ~6 concurrent streams per browser per domain.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">One Direction Only</div>\n      <div class=\"concept-def\"><strong>SSE is server-to-client only.</strong> The client cannot send data back on the same connection. For any client action (user sends a message, acknowledges a notification), you make a separate REST/HTTP POST call.<br><span style=\"color:#5a5848;font-size:12.5px;\">This is the key difference from WebSocket. In most notification/feed systems this is fine \u2014 client-to-server actions are already REST calls.</span></div>\n    </div>\n  </div>\n\n  <h3>Long Polling \u2014 How It Actually Works</h3>\n  <div class=\"concept-grid\">\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">The Mechanism</div>\n      <div class=\"concept-def\"><strong>Step by step:</strong><br>\n        1. Client sends <code>GET /messages?since=1234</code><br>\n        2. Server checks if new messages exist. If yes \u2192 respond immediately. If no \u2192 <strong>hold the connection open</strong><br>\n        3. When a message arrives, server responds with it<br>\n        4. Client receives response, <strong>immediately sends a new request</strong><br>\n        5. Repeat forever<br>\n        <span style=\"color:#5a5848;font-size:12.5px;\">Timeout: if no data after 30 seconds, server responds with 204 No Content. Client retries. This prevents proxy timeouts.</span>\n      </div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">vs Regular Polling</div>\n      <div class=\"concept-def\"><strong>Regular polling</strong>: client asks every N seconds regardless. Empty responses waste bandwidth and add N seconds of latency.<br><strong>Long polling</strong>: client asks once, server responds only when there's data. Near-zero latency, zero empty responses.<br><span style=\"color:#1a7a4a;font-size:12.5px;\">\u2713 Long polling is near-real-time with standard HTTP. No WebSocket, no special protocol. Works everywhere HTTP works.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">Scalability Challenge</div>\n      <div class=\"concept-def\"><strong>Long polling holds server threads/connections open while waiting.</strong> With 100K concurrent users each holding a long poll connection, you need 100K open connections on your servers \u2014 consuming file descriptors and memory even when idle.<br><span style=\"color:#b83030;font-size:12.5px;\">\u26a0\ufe0f Mitigate with async event loops (Node.js, Go goroutines, Nginx) that handle thousands of open connections on a single thread. Traditional thread-per-request servers (Java/Rails) cannot scale long polling.</span></div>\n    </div>\n    <div class=\"concept-row\">\n      <div class=\"concept-term\">When Still Used</div>\n      <div class=\"concept-def\"><strong>Long polling is the fallback when WebSocket is unavailable</strong> (corporate firewalls blocking WS) or for systems where you need guaranteed delivery with replay.<br><span style=\"color:#5a5848;font-size:12.5px;\">Real usage: Slack originally used long polling before WebSocket. Some mobile apps in restricted networks still use it. XMPP Bosh protocol is long polling. Most modern systems use WebSocket or SSE instead.</span></div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 03 FULL COMPARISON \u2550\u2550 -->\n<section id=\"comparison\">\n  <div class=\"sec-tag\">03 \u00b7 Side by Side</div>\n  <h2>Every dimension that matters in an interview</h2>\n\n  <table class=\"comp-table\">\n    <thead>\n      <tr>\n        <th>Dimension</th>\n        <th>REST \ud83c\udf10</th>\n        <th>gRPC \u26a1</th>\n        <th>GraphQL \u25c8</th>\n        <th>WebSocket \ud83d\udd0c</th>\n        <th>SSE \ud83d\udce1</th>\n        <th>Long Poll \ud83d\udd04</th>\n      </tr>\n    </thead>\n    <tbody>\n      <tr>\n        <td class=\"row-head\">Communication</td>\n        <td>Request-Response</td>\n        <td>RPC + Streaming</td>\n        <td>Request-Response</td>\n        <td>Bidirectional</td>\n        <td>Server\u2192Client</td>\n        <td>Simulated Push</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Transport</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/2 only</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>TCP (after upgrade)</td>\n        <td>HTTP/1.1, HTTP/2</td>\n        <td>HTTP/1.1, HTTP/2</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Data Format</td>\n        <td>JSON, XML, anything</td>\n        <td>Protobuf (binary)</td>\n        <td>JSON</td>\n        <td>Any (text or binary)</td>\n        <td>Text (UTF-8)</td>\n        <td>JSON, anything</td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Latency</td>\n        <td><span class=\"warn\">1 RTT per request</span></td>\n        <td><span class=\"good\">~1 RTT, multiplexed</span></td>\n        <td><span class=\"warn\">1 RTT per query</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"good\">Sub-ms after connect</span></td>\n        <td><span class=\"warn\">~1 RTT when data ready</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Payload Size</td>\n        <td><span class=\"warn\">Large (JSON + HTTP headers)</span></td>\n        <td><span class=\"good\">5\u201310x smaller than REST</span></td>\n        <td><span class=\"warn\">Similar to REST</span></td>\n        <td><span class=\"good\">Tiny frame headers</span></td>\n        <td><span class=\"good\">Small (text events)</span></td>\n        <td><span class=\"warn\">HTTP headers per request</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">HTTP Caching</td>\n        <td><span class=\"good\">Full support (GET)</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"bad\">None natively</span></td>\n        <td><span class=\"bad\">None</span></td>\n        <td><span class=\"warn\">Limited</span></td>\n        <td><span class=\"bad\">None effectively</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Browser Support</td>\n        <td><span class=\"good\">Universal</span></td>\n        <td><span class=\"bad\">Needs gRPC-Web proxy</span></td>\n        <td><span class=\"good\">Universal (HTTP)</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">All modern browsers</span></td>\n        <td><span class=\"good\">Universal</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Stateful?</td>\n        <td><span class=\"good\">Stateless</span></td>\n        <td><span class=\"warn\">Stream is stateful</span></td>\n        <td><span class=\"good\">Stateless (queries)</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"bad\">Stateful connection</span></td>\n        <td><span class=\"warn\">Quasi-stateful</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Load Balancing</td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"good\">L7 with gRPC-aware LB</span></td>\n        <td><span class=\"good\">Trivial</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"bad\">Sticky sessions needed</span></td>\n        <td><span class=\"warn\">Manageable</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Schema / Contract</td>\n        <td><span class=\"warn\">Optional (OpenAPI)</span></td>\n        <td><span class=\"good\">Mandatory .proto</span></td>\n        <td><span class=\"good\">Typed schema</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n        <td><span class=\"bad\">None by default</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Tooling / Ecosystem</td>\n        <td><span class=\"good\">Massive</span></td>\n        <td><span class=\"warn\">Good, growing</span></td>\n        <td><span class=\"good\">Rich (Apollo, Relay)</span></td>\n        <td><span class=\"warn\">Good</span></td>\n        <td><span class=\"warn\">Lightweight</span></td>\n        <td><span class=\"warn\">Basic</span></td>\n      </tr>\n      <tr>\n        <td class=\"row-head\">Best For</td>\n        <td>Public APIs, CRUD</td>\n        <td>Internal services</td>\n        <td>Multi-client APIs</td>\n        <td>Chat, games, collab</td>\n        <td>Feeds, notifications</td>\n        <td>Legacy/fallback</td>\n      </tr>\n    </tbody>\n  </table>\n</section>\n\n<!-- \u2550\u2550 04 COMBOS \u2550\u2550 -->\n<section id=\"combos\">\n  <div class=\"sec-tag\">04 \u00b7 Where They Complement Each Other</div>\n  <h2>Protocols that work together \u2014 not against each other</h2>\n\n  <p>The biggest interview insight: <strong>real systems use multiple protocols simultaneously</strong>. The request-response and real-time families solve different problems and are designed to be combined. Here are the six most common patterns you'll see and need to justify in interviews.</p>\n\n  <div class=\"combo-grid\">\n\n    <div class=\"combo-card c1\">\n      <div class=\"combo-title\">REST + WebSocket</div>\n      <div class=\"combo-formula\">REST for actions \u00b7 WebSocket for events</div>\n      <div class=\"combo-body\">REST handles all mutations (send message, create post, update status). WebSocket delivers the real-time events (new message received, presence change, typing indicator). The REST call triggers the server-side change; WebSocket broadcasts the result to affected users.</div>\n      <div class=\"combo-used\">Used by: Slack, Discord, WhatsApp Web, Notion</div>\n    </div>\n\n    <div class=\"combo-card c2\">\n      <div class=\"combo-title\">REST + SSE</div>\n      <div class=\"combo-formula\">REST for writes \u00b7 SSE for live updates</div>\n      <div class=\"combo-body\">User submits actions via REST (POST /start-analysis). Server acknowledges immediately with a job ID. SSE stream delivers progress updates as the job runs. Simpler than WebSocket because the client never needs to send mid-stream. Classic for progress bars, live dashboards, AI streaming responses.</div>\n      <div class=\"combo-used\">Used by: GitHub Actions, Vercel deployments, OpenAI API (streaming tokens), monitoring dashboards</div>\n    </div>\n\n    <div class=\"combo-card c3\">\n      <div class=\"combo-title\">REST (external) + gRPC (internal)</div>\n      <div class=\"combo-formula\">REST at the edge \u00b7 gRPC between services</div>\n      <div class=\"combo-body\">Public API exposed as REST \u2014 universal browser support, HTTP caching, familiar to all clients. Internal microservice calls use gRPC \u2014 5\u201310x smaller payloads, strict typed contracts, HTTP/2 multiplexing. An API Gateway (like Envoy or Kong) translates REST\u2192gRPC at the boundary.</div>\n      <div class=\"combo-used\">Used by: Google, Uber, Netflix, most FAANG internal architectures</div>\n    </div>\n\n    <div class=\"combo-card c4\">\n      <div class=\"combo-title\">GraphQL + WebSocket</div>\n      <div class=\"combo-formula\">GraphQL Queries/Mutations + GraphQL Subscriptions</div>\n      <div class=\"combo-body\">GraphQL queries and mutations travel over HTTP for reads and writes. GraphQL Subscriptions use WebSocket under the hood for real-time updates. One unified schema \u2014 the client uses the same GraphQL types and vocabulary for both. Apollo Client handles both transports automatically.</div>\n      <div class=\"combo-used\">Used by: GitHub (GraphQL API + subscriptions), Hasura, Shopify Storefront API</div>\n    </div>\n\n    <div class=\"combo-card c5\">\n      <div class=\"combo-title\">REST + Long Polling (legacy)</div>\n      <div class=\"combo-formula\">REST everywhere \u00b7 Long polling as fallback</div>\n      <div class=\"combo-body\">When WebSocket or SSE is blocked by corporate firewalls or unsupported by old clients, long polling bridges the gap. Standard REST for all actions; long polling for the notification channel. Socket.io does exactly this \u2014 it tries WebSocket first, falls back to long polling automatically.</div>\n      <div class=\"combo-used\">Used by: Socket.io fallback, legacy enterprise apps, restricted network environments</div>\n    </div>\n\n    <div class=\"combo-card c6\">\n      <div class=\"combo-title\">gRPC Bidirectional Streaming</div>\n      <div class=\"combo-formula\">One protocol, four modes</div>\n      <div class=\"combo-body\">For pure service-to-service real-time, gRPC bidirectional streaming replaces both REST and WebSocket. Both sides stream simultaneously over a single HTTP/2 connection. Used for location tracking (client streams GPS, server streams route), audio/video processing, real-time ML inference pipelines.</div>\n      <div class=\"combo-used\">Used by: Google Maps, real-time ML pipelines, internal FAANG service meshes</div>\n    </div>\n\n  </div>\n\n  <div class=\"callout cl-green\">\n    <div class=\"cl-lbl\">The Interview Sound Bite</div>\n    <p><strong>\"In most production systems I would use REST for the request-response layer and pair it with either SSE or WebSocket for the real-time layer \u2014 depending on whether the client needs to send data back on the same connection. REST handles mutations; the real-time channel delivers server-initiated events. gRPC replaces REST for internal service-to-service calls where latency and throughput matter.\"</strong></p>\n  </div>\n</section>\n\n<!-- \u2550\u2550 05 SYSTEM DESIGN EXAMPLES \u2550\u2550 -->\n<section id=\"examples\">\n  <div class=\"sec-tag\">05 \u00b7 Applied to Real Systems</div>\n  <h2>Which protocol wins in which system?</h2>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Chat App (Slack / WhatsApp)</div>\n      <span class=\"sd-example-tag\">BIDIRECTIONAL \u00b7 REAL-TIME</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">SEND MESSAGE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>POST /messages</code> \u2014 client sends message, server persists it, returns message ID + timestamp. REST because: idempotency key prevents duplicates on retry, HTTP status codes signal delivery failure clearly, easy to rate-limit with standard middleware.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">RECEIVE MESSAGES</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Server pushes new messages to all room members the moment they arrive. Bidirectional needed: client also sends typing indicators and read receipts back on the same connection. Sub-10ms delivery vs 1\u20135 second polling lag.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PRESENCE / TYPING</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is typing\u2026\" \u2014 client sends typing events over the WebSocket every keystroke. Server fans out to all members via pub/sub (Redis). Low-overhead frames, no HTTP headers per event.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL SERVICES</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Message Service \u2192 Notification Service \u2192 Presence Service: all internal. Protobuf contracts prevent schema drift. HTTP/2 multiplexing handles thousands of RPCs/sec between services without connection explosion.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT ALL WS</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Tradeoff \u26a0</span> WebSocket for everything seems elegant but: WS mutations can't use HTTP caching, rate limiting is harder, retry logic needs custom implementation, and load balancing requires sticky sessions. REST for writes + WS for events is the industry standard split.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Top-K Trending Dashboard (YouTube / Twitter)</div>\n      <span class=\"sd-example-tag\">SERVER PUSH \u00b7 READ-HEAVY</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">LIVE RANKINGS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Dashboard shows top 10 videos updating every 30 seconds. SSE stream pushes updates from Flink flush events. Client never sends data back \u2014 perfect SSE fit. Auto-reconnect handles network hiccups transparently. HTTP/2 multiplexes thousands of concurrent dashboard viewers.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INITIAL DATA LOAD</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> <code>GET /top-k?window=1h&region=IN</code> loads the initial ranked list. Cacheable at CDN edge (60s TTL). 95% of requests served from cache \u2014 SSE stream only delivers delta updates after the initial load.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT WEBSOCKET</div>\n        <div class=\"choice-val\"><span class=\"badge b-a\">Overkill \u26a0</span> The dashboard is read-only \u2014 users never push data back. WebSocket's bidirectional capability is wasted. SSE is simpler: no handshake upgrade, works through HTTP/2 proxies without special configuration, auto-reconnects, and uses standard HTTP connections that load balancers understand natively.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WHY NOT POLLING</div>\n        <div class=\"choice-val\"><span class=\"badge b-r\">Inefficient \u2717</span> At 30s poll interval and 100K concurrent users: 100K requests every 30s = 3,333 requests/sec, most returning the same data. SSE uses a persistent connection per user \u2014 0 requests until data changes. Orders of magnitude less origin traffic.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Mobile App API (Instagram / Uber)</div>\n      <span class=\"sd-example-tag\">MULTI-CLIENT \u00b7 BANDWIDTH-SENSITIVE</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Desktop browser with good connectivity. REST with HTTP/2 is fast, cacheable, and familiar. No over-fetching problem at this scale \u2014 one REST response per screen is acceptable.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE APP API</div>\n        <div class=\"choice-val\"><span class=\"badge b-gql\">GraphQL \u2713</span> Mobile on 4G/5G with limited bandwidth. GraphQL lets the app fetch exactly the fields it needs \u2014 no wasted data. One query fetches feed + stories + story counts instead of 3 REST calls. Instagram's move to GraphQL reduced API response sizes by 30\u201350%.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">PARTNER API</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Third-party developer integrations use REST. Universal support, simple to understand, extensive documentation. GraphQL's flexibility is a liability here \u2014 partners need a stable, versioned contract, not an evolving schema.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DRIVER LOCATION (Uber)</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Driver app streams GPS location every 2 seconds. Rider app receives driver position updates in real-time. Both directions active simultaneously \u2014 classic WebSocket scenario. gRPC bidirectional streaming works equally well for this internal use case.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Notification System (Apple Push / Firebase)</div>\n      <span class=\"sd-example-tag\">FAN-OUT \u00b7 MOBILE PUSH</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">WEB NOTIFICATIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-sse\">SSE \u2713</span> Browser tab receives notifications via SSE stream. User doesn't send acknowledgements in the same connection \u2014 REST POST for \"mark as read\". Simple, reconnects automatically, works with HTTP/2.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">MOBILE PUSH</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Your server calls APNs (Apple) or FCM (Firebase) REST APIs to push notifications to iOS/Android. The OS maintains its own persistent connection to Apple/Google \u2014 you just trigger it via REST. Your app never holds a WebSocket open in the background.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">INTERNAL FAN-OUT</div>\n        <div class=\"choice-val\"><span class=\"badge b-grpc\">gRPC \u2713</span> Notification Service fans out to User Service, Device Service, and APNs Gateway all via gRPC. Hundreds of millions of notifications/day means every millisecond and byte of payload overhead compounds. Protobuf binary encoding + HTTP/2 multiplexing handles the load.</div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"sd-example\">\n    <div class=\"sd-example-head\">\n      <div class=\"sd-example-title\">Collaborative Editing (Google Docs / Notion)</div>\n      <span class=\"sd-example-tag\">CRDT \u00b7 REAL-TIME \u00b7 MULTI-USER</span>\n    </div>\n    <div class=\"sd-example-body\">\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">EDITS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> Every keystroke is an operation (insert/delete + position). Operations are sent over WebSocket immediately. Server applies OT (Operational Transformation) or CRDT to merge concurrent edits from multiple users. The merged result is broadcast back to all connected users via the same WebSocket.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">CURSOR POSITIONS</div>\n        <div class=\"choice-val\"><span class=\"badge b-ws\">WebSocket \u2713</span> \"Alice is editing paragraph 3\" \u2014 cursor broadcast via WebSocket at ~10 events/sec. Ephemeral \u2014 not persisted. WebSocket's low per-frame overhead makes this affordable even for documents with 50 simultaneous editors.</div>\n      </div>\n      <div class=\"choice-row\">\n        <div class=\"choice-label\">DOCUMENT SAVE</div>\n        <div class=\"choice-val\"><span class=\"badge b-rest\">REST \u2713</span> Periodic snapshot of document state sent via REST POST. Idempotent, retryable, separate from the real-time stream. REST for durability; WebSocket for real-time sync.</div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 06 DECISION TREE \u2550\u2550 -->\n<section id=\"decision\">\n  <div class=\"sec-tag\">06 \u00b7 The Decision Framework</div>\n  <h2>How to pick in an interview \u2014 in 60 seconds</h2>\n\n  <div class=\"step-block\">\n    <div class=\"step-block-header\"><span class=\"sb-icon\">\ud83c\udfaf</span>Protocol Selection \u2014 Ask in Order</div>\n    <div class=\"step-block-body\">\n      <div class=\"step-row\"><div class=\"step-num\">01</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the server need to push data to the client without the client asking?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\">You need a real-time protocol. Go to Step 2. REST alone cannot solve this.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\">Request-Response is sufficient. Go to Step 4 to pick between REST, gRPC, and GraphQL.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">02</div><div class=\"step-content\">\n        <div class=\"step-q\">Does the client also need to send data back on the same real-time connection?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">YES \u2192</span><span class=\"opt-text\"><strong>WebSocket.</strong> Chat messages, cursor positions, game inputs, collaborative edits \u2014 bidirectional continuous communication. Pair with REST for mutations that need HTTP semantics (retries, idempotency).</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">NO \u2192</span><span class=\"opt-text\"><strong>SSE</strong> (preferred) or <strong>Long Polling</strong> (fallback). Live feeds, notifications, progress bars, dashboards \u2014 server pushes, client only reads. SSE is simpler and HTTP/2-native. Long Polling if SSE is unavailable.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">03</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this for browser clients or internal service-to-service?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Browser \u2192</span><span class=\"opt-text\"><strong>WebSocket or SSE.</strong> Both have native browser APIs (WebSocket API, EventSource API). No proxy needed.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Service-to-Service \u2192</span><span class=\"opt-text\"><strong>gRPC bidirectional streaming</strong> \u2014 all the benefits of gRPC (binary, typed, multiplexed) plus both sides can stream. Google Maps, real-time ML inference pipelines.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">04</div><div class=\"step-content\">\n        <div class=\"step-q\">Is this a public API, internal service, or multi-client API?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Public API \u2192</span><span class=\"opt-text\"><strong>REST.</strong> Universal support, HTTP caching, familiar to all developers, simple to rate limit and monitor. Default until you have a specific reason to deviate.</span></div>\n          <div class=\"step-option opt-mid\"><span class=\"opt-arrow\">Internal services \u2192</span><span class=\"opt-text\"><strong>gRPC.</strong> Binary Protobuf (5\u201310x smaller), HTTP/2 multiplexing, strict typed contracts. Ideal for service meshes where latency and throughput compound across hundreds of microservices.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Multi-client (web + mobile + partners) \u2192</span><span class=\"opt-text\"><strong>GraphQL.</strong> Different clients need different data shapes. One schema, client-driven queries, no over-fetching on mobile bandwidth. Requires DataLoader to avoid N+1.</span></div>\n        </div>\n      </div></div>\n      <div class=\"step-row\"><div class=\"step-num\">05</div><div class=\"step-content\">\n        <div class=\"step-q\">Do you have strict performance or bandwidth requirements?</div>\n        <div class=\"step-options\">\n          <div class=\"step-option opt-yes\"><span class=\"opt-arrow\">Performance critical \u2192</span><span class=\"opt-text\"><strong>gRPC over REST</strong> for service-to-service. Binary vs JSON: 5\u201310x payload reduction. At 1M RPC/sec between services, the difference is measurable in infra costs and latency percentiles.</span></div>\n          <div class=\"step-option opt-no\"><span class=\"opt-arrow\">Standard requirements \u2192</span><span class=\"opt-text\"><strong>REST is fine.</strong> With HTTP/2 and proper JSON compression (gzip/brotli), REST performance is excellent for the vast majority of systems. Don't optimise prematurely.</span></div>\n        </div>\n      </div></div>\n    </div>\n  </div>\n\n  <h3>The Rules You Must Know</h3>\n  <div class=\"use-grid\">\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--rest)\">\ud83c\udf10 Always use REST when\u2026</div>\n      <ul>\n        <li>Building a public-facing API</li>\n        <li>Need HTTP caching (GET responses)</li>\n        <li>Clients are diverse (browsers, mobile, partners)</li>\n        <li>Team is small, simplicity matters</li>\n        <li>CRUD operations with standard semantics</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--grpc)\">\u26a1 Always use gRPC when\u2026</div>\n      <ul>\n        <li>Service-to-service internal calls</li>\n        <li>High-throughput, latency-sensitive RPCs</li>\n        <li>Need strong schema contract between teams</li>\n        <li>Polyglot microservices (code gen handles language)</li>\n        <li>Streaming between services (bidirectional)</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--gql)\">\u25c8 Always use GraphQL when\u2026</div>\n      <ul>\n        <li>Multiple client types with different data needs</li>\n        <li>Mobile bandwidth is constrained</li>\n        <li>Rapidly evolving product with frequent data shape changes</li>\n        <li>BFF (Backend-for-Frontend) pattern</li>\n        <li>Developer experience is a priority</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--ws)\">\ud83d\udd0c Always use WebSocket when\u2026</div>\n      <ul>\n        <li>Chat or messaging (bidirectional)</li>\n        <li>Multiplayer games or real-time collaboration</li>\n        <li>Both client AND server need to push continuously</li>\n        <li>Sub-100ms latency for every event</li>\n        <li>Persistent session with many small messages</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--sse)\">\ud83d\udce1 Always use SSE when\u2026</div>\n      <ul>\n        <li>Server pushes, client only reads</li>\n        <li>Live dashboards, feeds, notifications</li>\n        <li>AI streaming responses (token-by-token)</li>\n        <li>Progress bars for long-running jobs</li>\n        <li>Simpler alternative to WebSocket</li>\n      </ul>\n    </div>\n    <div class=\"use-card\">\n      <div class=\"use-card-head\" style=\"color:var(--lp)\">\ud83d\udd04 Long Polling only when\u2026</div>\n      <ul>\n        <li>WebSocket and SSE are unavailable (firewalls)</li>\n        <li>Legacy client support required</li>\n        <li>Using Socket.io (handles fallback automatically)</li>\n        <li>Low update frequency (&lt;1/min) where polling gap is fine</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n<!-- \u2550\u2550 07 FOLLOW-UPS \u2550\u2550 -->\n<section id=\"followups\">\n  <div class=\"sec-tag\">07 \u00b7 Interview Follow-up Playbook</div>\n  <h2>Every hard follow-up, answered</h2>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you scale WebSocket to millions of concurrent connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>The core challenge:</strong> WebSocket connections are stateful and live on a specific server. Standard round-robin load balancing breaks \u2014 if user A is connected to server 1 and sends a message to user B connected to server 3, server 1 can't directly push to user B.<br><br>\n      <strong>The solution \u2014 pub/sub message bus:</strong>\n      <ul>\n        <li>Every server subscribes to a Redis Pub/Sub channel or Kafka topic</li>\n        <li>When server 1 needs to push to user B (connected to server 3), it publishes to the shared channel</li>\n        <li>Server 3 is subscribed, receives the message, and pushes it to user B's WebSocket connection</li>\n        <li>Any server can reach any user \u2014 no sticky sessions required for message delivery</li>\n      </ul>\n      <strong>Connection count:</strong> A single server with an async event loop (Node.js, Go, Nginx) can handle 100K\u20131M concurrent WebSocket connections. C10M is achievable with tuned Linux kernel settings (file descriptor limits, socket buffer sizes).<br><br>\n      <strong>Load balancing:</strong> Use sticky sessions (consistent hash by user_id) so a user's connection always routes to the same server \u2014 reduces pub/sub overhead. Failover: client reconnects to any available server on disconnect.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">REST vs gRPC \u2014 which is faster and by how much?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>In benchmarks, gRPC is typically 5\u201310x faster than JSON REST for equivalent payloads.</strong><br><br>\n      <strong>Why Protobuf is faster than JSON:</strong>\n      <ul>\n        <li><strong>Size:</strong> JSON is human-readable text. \"created_at\": \"2026-03-20T14:23:45Z\" is 37 bytes. Protobuf field 5 = timestamp = 8 bytes. 4\u20135x smaller is typical.</li>\n        <li><strong>Parsing:</strong> JSON parsing is string scanning and Unicode handling. Protobuf parsing is integer-indexed field lookup. 5\u201310x faster deserialization.</li>\n        <li><strong>HTTP/2 multiplexing:</strong> gRPC reuses one TCP connection for all RPCs between two services. HTTP/1.1 REST requires a connection per request or connection pooling.</li>\n      </ul>\n      <strong>Real-world numbers (Google's internal benchmarks):</strong> gRPC serialization is ~7x faster than JSON, payloads are ~3.5x smaller, leading to ~2\u20134x fewer CPU cycles per RPC.<br><br>\n      <strong>When the difference matters:</strong> At 10K RPC/sec between services, the CPU savings from Protobuf are measurable in infra cost. At 100 RPC/sec, use REST \u2014 the operational simplicity outweighs any performance gain.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">GraphQL solves over-fetching \u2014 but doesn't it create its own performance problems?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Yes \u2014 GraphQL solves bandwidth but creates three new challenges:</strong><br><br>\n      <strong>1. N+1 queries (the biggest one):</strong> A query for 100 posts each needing their author resolves by calling getAuthor() 100 times. Without DataLoader, this is 101 database calls instead of 2.<br>\n      Fix: DataLoader batches all getAuthor() calls that occur in the same tick into one <code>SELECT * FROM users WHERE id IN (1,2,3...100)</code>.<br><br>\n      <strong>2. Query complexity attacks:</strong> A malicious client sends a deeply nested query: posts \u2192 comments \u2192 authors \u2192 posts \u2192 comments \u2192 authors \u2192 (\u221e). Without depth limiting, this triggers exponential resolver calls.<br>\n      Fix: Query depth limit (max 10 levels), query complexity scoring (each field costs points, reject queries over a budget), query whitelisting in production (only allow known queries).<br><br>\n      <strong>3. No HTTP caching:</strong> GraphQL uses POST \u2014 CDNs don't cache POST. Every query hits your origin.<br>\n      Fix: Persisted Queries \u2014 hash each known query, send the hash as a GET parameter. CDN caches the response. Only novel/uncached queries reach the origin.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">SSE vs WebSocket \u2014 when exactly do you pick SSE?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Pick SSE when the data flow is one-directional and you want HTTP-native simplicity.</strong><br><br>\n      <strong>SSE wins over WebSocket when:</strong>\n      <ul>\n        <li>Client only reads \u2014 never sends data on the real-time channel (notifications, feeds, dashboards, AI token streaming)</li>\n        <li>You need automatic reconnection with event replay \u2014 SSE's <code>Last-Event-ID</code> mechanism gives you this for free; WebSocket requires custom client logic</li>\n        <li>HTTP/2 is available \u2014 SSE over HTTP/2 multiplexes thousands of streams over one TCP connection, solving HTTP/1.1's 6-connection limit</li>\n        <li>Your infrastructure doesn't support WebSocket upgrades (some corporate proxies block it)</li>\n        <li>You want standard HTTP monitoring, logging, and load balancing without special WebSocket-aware tooling</li>\n      </ul>\n      <strong>WebSocket wins when:</strong>\n      <ul>\n        <li>Client sends data frequently on the real-time channel (chat, collaborative editing, games, cursor positions)</li>\n        <li>Sub-frame latency matters \u2014 WebSocket frames are slightly lower overhead than SSE's HTTP text envelope</li>\n        <li>You need binary data (WebSocket supports binary frames natively; SSE is text-only)</li>\n      </ul>\n      <strong>The practical test:</strong> Draw an arrow for your data flow. If the arrow points server\u2192client only, use SSE. If arrows go both directions, use WebSocket.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How does gRPC handle versioning when you change your .proto schema?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Protobuf has designed-in backwards compatibility rules \u2014 but you must follow them religiously.</strong><br><br>\n      <strong>Safe changes (backwards and forwards compatible):</strong>\n      <ul>\n        <li>Adding a new field \u2014 old clients ignore it, new clients read it</li>\n        <li>Changing a field name \u2014 field numbers are what Protobuf uses on the wire, not names</li>\n        <li>Adding a new RPC method \u2014 old clients don't call it</li>\n      </ul>\n      <strong>Breaking changes (never do these in production):</strong>\n      <ul>\n        <li>Changing a field's number (field number = wire identity; changing it means old clients misread your data)</li>\n        <li>Changing a field's type (int32 \u2192 string will corrupt data in-flight)</li>\n        <li>Removing a required field (old clients still send it; new server rejects it)</li>\n        <li>Removing an RPC method that clients are calling</li>\n      </ul>\n      <strong>The strategy for major changes:</strong> Create a new package version (<code>package myapi.v2</code>). Run v1 and v2 in parallel. Migrate clients to v2 gradually. Retire v1 only after all clients have migrated. This is identical to REST's <code>/v1/</code> vs <code>/v2/</code> URL versioning.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">What's the difference between REST idempotency and GraphQL mutation safety?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Idempotency means: calling the operation multiple times has the same effect as calling it once.</strong><br><br>\n      <strong>REST's HTTP methods have defined idempotency semantics:</strong>\n      <ul>\n        <li><code>GET, HEAD, OPTIONS</code> \u2014 safe (no side effects) and idempotent</li>\n        <li><code>PUT, DELETE</code> \u2014 idempotent (doing it twice = same result as once)</li>\n        <li><code>POST</code> \u2014 neither safe nor idempotent (creates a new resource each call)</li>\n        <li><code>PATCH</code> \u2014 not inherently idempotent (depends on implementation)</li>\n      </ul>\n      <strong>For POST idempotency:</strong> Use an Idempotency-Key header (unique UUID per request). Server stores the key \u2192 result mapping. If same key arrives twice, return the stored result instead of executing again. Stripe, Stripe, and most payment APIs require this.<br><br>\n      <strong>GraphQL mutations:</strong> All mutations use POST \u2014 no built-in idempotency. You must implement idempotency keys manually in your mutation resolvers if needed (e.g., payment mutations). This is GraphQL's operational weakness vs REST's verb semantics.<br><br>\n      <strong>Why it matters in interviews:</strong> Payment processing, order creation, and any mutation where double-execution has real consequences needs explicit idempotency handling regardless of protocol.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">How do you secure WebSocket connections?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>WebSocket has no built-in authentication \u2014 you must implement it explicitly.</strong><br><br>\n      <strong>Step 1 \u2014 Use WSS (WebSocket Secure):</strong> Always use <code>wss://</code> (TLS), never <code>ws://</code>. Same as HTTPS vs HTTP. Your certificate covers both.<br><br>\n      <strong>Step 2 \u2014 Authenticate at connection time:</strong> The HTTP Upgrade request is a standard HTTP request \u2014 you can read headers and cookies. Send a JWT or session token in the <code>Authorization</code> header or as a query parameter on the initial <code>wss://</code> URL. Validate before accepting the upgrade.<br><br>\n      <strong>Step 3 \u2014 Authorise at message time:</strong> Validate that the connected user has permission for every message they send. Don't assume that because they connected legitimately, all their subsequent messages are authorised.<br><br>\n      <strong>Step 4 \u2014 Rate limit messages:</strong> Unlike HTTP where rate limiting is standard middleware, WebSocket bypasses your HTTP layer. Implement per-connection message rate limiting at the WebSocket handler level. Without it, one client can flood your server with messages.<br><br>\n      <strong>Step 5 \u2014 Handle token expiry:</strong> JWTs expire. If a user's token expires mid-session, the server needs to close the WebSocket and force re-authentication. Implement token refresh via a REST call; send the new token over the WebSocket or reconnect with the new token.\n    </div>\n  </div>\n\n  <div class=\"faq-item\">\n    <div class=\"faq-q\" onclick=\"toggle(this)\">In the Uber system design, why use both REST and WebSocket \u2014 why not just WebSocket for everything?<span class=\"tog\">+</span></div>\n    <div class=\"faq-a\">\n      <strong>Using WebSocket for everything seems elegant but creates real problems:</strong><br><br>\n      <strong>1. HTTP semantics matter:</strong> REST gives you status codes (400 bad request, 402 payment required, 409 conflict) that load balancers, monitoring tools, and clients all understand natively. Over WebSocket, you'd invent custom error codes \u2014 invisible to your infrastructure.<br><br>\n      <strong>2. Idempotency and retries:</strong> When a user books a ride, you need idempotency guarantees. REST POST with an Idempotency-Key is standardised. WebSocket message delivery is at-most-once by default \u2014 you'd need to build your own ack/retry layer.<br><br>\n      <strong>3. Caching:</strong> Fare estimates, driver profiles, and static data are cacheable. REST GET responses are cached at CDN and browser level automatically. WebSocket has no caching layer.<br><br>\n      <strong>4. Load balancing:</strong> REST requests are stateless \u2014 any server handles any request. WebSocket connections are stateful \u2014 they need sticky sessions or a message bus. Running everything over WebSocket means every service needs WebSocket-aware infrastructure.<br><br>\n      <strong>5. Operational tooling:</strong> HTTP logs, traces, and metrics are supported by every monitoring tool out of the box. WebSocket message-level observability requires custom instrumentation.<br><br>\n      <strong>The correct split:</strong> WebSocket for what genuinely needs real-time bidirectional communication (location, status updates). REST for everything transactional (booking, payment, profile). The complexity-to-benefit ratio is much better.\n    </div>\n  </div>\n</section>\n\n</div>\n<div class=\"footer\">PROTOCOLS \u00b7 REST \u00b7 GRPC \u00b7 GRAPHQL \u00b7 WEBSOCKET \u00b7 SSE \u00b7 LONG POLLING \u00b7 MANISH-ALMANAC</div>\n\n\u003cscript>function toggle(el){el.parentElement.classList.toggle('open');}<\/script>\n</body>\n</html>\n", tag: 'Protocols' }
};

function openCollection(){
  document.getElementById('list').style.display='none';
  document.getElementById('coll-panel').classList.add('open');
}
function closeCollection(){
  document.getElementById('coll-item').classList.remove('open');
  var f=document.getElementById('ci-iframe');if(f)f.srcdoc='';
  document.getElementById('coll-panel').classList.remove('open');
  document.getElementById('list').style.display='block';
}
function openCollItem(id){
  var item=COLLECTION_DATA[id];
  if(!item)return;
  document.getElementById('ci-title').textContent=item.title;
  var iframe=document.getElementById('ci-iframe');
  document.getElementById('coll-item').classList.add('open');
  if(item.srcdoc){
    /* embedded — works on file://, GitHub Pages, everywhere */
    iframe.srcdoc=item.srcdoc;
  } else {
    /* fetch-based — for cms/topk/ai_handbook standalone files */
    iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;text-align:center;color:#aaa;font-size:14px">Loading…</div>';
    fetch(item.file)
      .then(function(r){ if(!r.ok)throw new Error('HTTP '+r.status); return r.text(); })
      .then(function(html){ iframe.srcdoc=html; })
      .catch(function(e){
        iframe.srcdoc='<div style="font-family:-apple-system,sans-serif;padding:40px 24px;color:#c00;font-size:14px">Could not load '+item.file+'.<br><small>'+e.message+'</small><br><br><small>Run via server: <code>python3 -m http.server</code></small></div>';
      });
  }
}
function closeCollItem(){
  document.getElementById('coll-item').classList.remove('open');
  /* Clear iframe to stop any running scripts */
  setTimeout(function(){
    var f=document.getElementById('ci-iframe');
    if(f)f.srcdoc='';
  },50);
}

function initCollection(){
  var pairs=[
    ['btn_collection',   function(){openCollection();}],
    ['btn_coll_back',    function(){closeCollection();}],
    ['btn_ci_back',      function(){closeCollItem();}],
    ['btn_coll_cms',     function(){openCollItem('cms');}],
    ['btn_coll_topk',    function(){openCollItem('topk');}],
    ['btn_coll_ai',      function(){openCollItem('ai_handbook');}],
    ['btn_coll_databases',function(){openCollItem('databases');}],
    ['btn_coll_olap',    function(){openCollItem('olap');}],
    ['btn_coll_streaming',function(){openCollItem('streaming');}],
    ['btn_coll_protocols',function(){openCollItem('protocols');}]
  ];
  pairs.forEach(function(p){
    var el=document.getElementById(p[0]);
    if(el) el.addEventListener('click',p[1]);
  });
}
